CPPG.mcq.push(

  /* ───── 1과목 ───── */
  { s:'s1', t:'개인정보 개념', d:3, q:'다음은 A 대학병원의 데이터 활용 계획이다.\n\n· 2019년에 사망한 환자의 진료기록을 연구용으로 보관하고 있다\n· 재직 교직원의 인사고과 평가 결과를 인사시스템에 저장한다\n· 외래환자의 예약 시 수집한 휴대전화번호를 상담 이력과 함께 관리한다\n· 진료 통계를 연령대·성별·지역 단위로만 집계해 홈페이지에 공개한다\n\n개인정보보호법상 "개인정보"에 해당하는 것을 옳게 묶은 것은?', c:['사망 환자 진료기록, 인사고과 결과','인사고과 결과, 외래환자 휴대전화번호·상담 이력','사망 환자 진료기록, 공개된 집계 통계','외래환자 휴대전화번호, 공개된 집계 통계'], a:1, e:'개인정보는 살아있는 개인에 관한 정보다. 사망자 정보는 제외되고, 복원 불가능한 집계 통계는 익명정보다. 인사고과 같은 주관적 평가도 개인정보에 포함된다.' },
  { s:'s1', t:'개인정보 개념', d:3, q:'다음 〈보기〉에서 개인정보보호법 제2조의 용어 정의에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. "처리"에는 수집·저장·이용뿐 아니라 파기까지 포함된다\nㄴ. "개인정보파일"은 개인정보를 쉽게 검색할 수 있도록 체계적으로 배열·구성한 집합물이다\nㄷ. "개인정보처리자"는 처리자의 지휘·감독을 받아 개인정보를 처리하는 자연인을 말한다\nㄹ. "정보주체"는 처리되는 정보에 의하여 알아볼 수 있는 사람으로서 그 정보의 주체가 되는 사람이다\nㅁ. "개인정보취급자"는 업무를 목적으로 개인정보파일을 운용하는 법인·단체·개인을 말한다', c:['ㄱ, ㄴ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'ㄷ과 ㅁ은 처리자와 취급자의 정의가 서로 바뀌었다. 의무 주체는 처리자, 지휘·감독을 받는 자연인은 취급자다.' },
  { s:'s1', t:'개인정보 개념', d:3, q:'B사는 회원 데이터를 다음과 같이 가공하여 외부 연구기관과 공동 분석을 하려 한다.\n\n· 이름은 삭제하고 생년월일은 출생연도만 남긴다\n· 회원번호는 별도 매핑표를 사내 금고에 보관한 뒤 임의의 코드로 대체한다\n· 가공된 데이터는 신규 광고 타깃팅 모델 학습에 활용할 예정이다\n\n이 계획에 대한 평가로 가장 옳은 것은?', c:['매핑표를 분리 보관했으므로 익명정보가 되어 법 적용을 받지 않는다','추가 정보로 복원이 가능하므로 가명정보이며, 광고 타깃팅은 동의 없이 처리할 수 있는 목적이 아니다','가명정보는 목적 제한 없이 동의 없이 처리할 수 있으므로 적법하다','가명정보라도 연구기관과의 결합은 처리자가 직접 수행할 수 있다'], a:1, e:'추가 정보로 복원 가능하면 가명정보(개인정보)다. 동의 없는 처리는 통계작성·과학적 연구·공익적 기록보존 목적에 한하며, 결합은 지정된 전문기관을 통해야 한다.' },
  { s:'s1', t:'개인정보 개념', d:3, q:'다음 〈보기〉에서 가명정보에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 통계작성·과학적 연구·공익적 기록보존 목적이면 정보주체 동의 없이 처리할 수 있다\nㄴ. 서로 다른 처리자 간 결합은 보호위원회 등이 지정한 전문기관이 수행한다\nㄷ. 가명정보를 파기한 경우 관련 기록은 파기한 날부터 1년 이상 보관하면 된다\nㄹ. 특정 개인을 알아볼 수 있는 정보가 생성되면 즉시 처리를 중지하고 지체 없이 회수·파기해야 한다\nㅁ. 가명정보에는 개인정보 유출 신고 의무도 적용되지 않는다', c:['ㄱ, ㄴ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'기록 보관은 파기한 날부터 3년 이상이며, 적용 제외는 제34조 제1항(통지)이지 신고 의무는 그대로 적용된다.' },
  { s:'s1', t:'개인정보 개념', d:2, q:'다음 중 개인정보의 식별성 판단과 결합 용이성에 대한 설명으로 옳지 않은 것은?', c:['결합에 소요되는 시간과 비용, 기술 수준을 합리적으로 고려하여 판단한다','그 정보만으로 알아볼 수 있는 경우뿐 아니라 다른 정보와 쉽게 결합하여 알아볼 수 있는 경우도 개인정보다','정보주체가 결합에 동의했는지 여부가 결합 용이성 판단의 핵심 기준이 된다','IP 주소나 쿠키는 그 자체로는 식별이 어렵더라도 다른 정보와 결합하면 개인정보가 될 수 있다'], a:2, e:'동의 여부는 적법성의 문제이지 식별성 판단 기준이 아니다.' },
  { s:'s1', t:'개인정보 개념', d:3, q:'다음 〈보기〉에서 민감정보에 해당하는 것을 모두 고른 것은?\n\nㄱ. 특정 개인을 알아볼 목적으로 처리하는 지문·홍채 등 생체인식정보\nㄴ. 외국인등록번호\nㄷ. 노동조합의 가입·탈퇴에 관한 정보\nㄹ. 유전자검사 등의 결과로 얻어진 유전정보\nㅁ. 형의 실효 등에 관한 법률에 따른 범죄경력자료', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄷ, ㄹ, ㅁ','ㄴ, ㄹ, ㅁ','ㄷ, ㄹ, ㅁ'], a:1, e:'외국인등록번호는 고유식별정보 4종 중 하나다. 생체인식정보·유전정보·범죄경력자료는 시행령이 정한 민감정보다.' },
  { s:'s1', t:'개인정보 개념', d:3, q:'C 인터넷 서비스는 회원가입 화면에서 주민등록번호를 수집하며 다음과 같이 운영한다.\n\n· "주민등록번호 수집·이용 동의" 항목을 별도 체크박스로 분리해 두었다\n· 수집한 주민등록번호는 접근권한을 제한한 채 평문으로 저장한다\n· 주민등록번호 외의 회원가입 방법은 제공하지 않는다\n\n이 운영에 대한 지적으로 옳게 묶인 것은?', c:['별도 동의로는 주민등록번호를 처리할 수 없음 · 예외 없이 암호화해야 함 · 대체수단을 제공해야 함','별도 동의를 받았으므로 수집은 적법하고 암호화만 보완하면 됨','접근권한을 제한했으므로 암호화는 위험도 분석 결과에 따라 생략할 수 있음','대체수단 제공 의무만 위반이며 나머지는 적법함'], a:0, e:'주민등록번호는 법령의 구체적 근거·급박한 이익·보호위원회 고시로만 처리 가능하며, 예외 없이 암호화하고 홈페이지 회원가입 시 대체수단을 제공해야 한다.' },
  { s:'s1', t:'개인정보 개념', d:2, q:'개인정보의 처리 근거에 관한 다음 설명 중 옳은 것은?', c:['민감정보는 별도 동의 또는 법령에서 요구·허용하는 경우에만 처리할 수 있다','고유식별정보는 정보주체의 일반적인 수집·이용 동의만 있으면 처리할 수 있다','주민등록번호는 정보주체의 별도 동의를 받으면 자유롭게 처리할 수 있다','민감정보는 안전성 확보조치 대상에서 제외된다'], a:0, e:'고유식별정보는 별도 동의 또는 법령의 구체적 근거가 필요하고, 주민등록번호는 동의로 처리할 수 없다. 민감정보는 안전조치 의무 대상이다.' },
  { s:'s1', t:'프라이버시·특성', d:3, q:'다음 〈보기〉에서 프라이버시와 개인정보 자기결정권에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 프라이버시권은 사생활의 평온을 침해받지 않을 소극적·방어적 권리다\nㄴ. 개인정보 자기결정권은 자신에 관한 정보를 스스로 결정·통제할 적극적 권리다\nㄷ. 개인정보 자기결정권은 헌법에 명시된 조문으로 직접 규정되어 있다\nㄹ. 개인정보는 권리 그 자체가 아니라 보호의 대상이다\nㅁ. 프라이버시권과 개인정보 자기결정권은 동일한 개념이다', c:['ㄱ, ㄴ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄷ, ㄹ'], a:0, e:'자기결정권은 헌법 제10조·제17조에서 도출된 기본권으로 헌법재판소가 인정한 것이며, 프라이버시권과는 성격이 다르다.' },
  { s:'s1', t:'프라이버시·특성', d:3, q:'다음은 개인정보의 특성을 설명한 것이다. 옳지 않은 것은?', c:['무형성 — 실체가 없어 복제·유통이 쉽고 통제가 어렵다','비소모성 — 반복 사용해도 소모되지 않아 재사용·재유통된다','회복 용이성 — 유출되더라도 회수·원상복구가 비교적 쉽다','가치 가변성 — 맥락과 시점에 따라 정보의 가치와 민감도가 달라진다'], a:2, e:'한 번 유출된 개인정보는 회수가 사실상 불가능하다. 그래서 사전 예방과 안전조치가 중요하다.' },
  { s:'s1', t:'프라이버시·특성', d:3, q:'다음 사례에서 침해가 발생한 라이프사이클 단계를 옳게 연결한 것은?\n\n(가) 회원가입 시 서비스 제공에 불필요한 직업·연소득까지 필수 항목으로 받았다\n(나) 상담 목적으로 받은 연락처를 신규 상품 광고 발송에 사용했다\n(다) 계약 종료 후 3년이 지난 거래 상대방 정보를 그대로 보관하고 있었다', c:['(가) 수집 — (나) 이용 — (다) 파기','(가) 이용 — (나) 제공 — (다) 보유','(가) 수집 — (나) 제공 — (다) 관리','(가) 관리 — (나) 이용 — (다) 파기'], a:0, e:'과다 수집은 수집 단계, 목적 외 이용은 이용 단계, 보유기간 경과 후 미파기는 파기 단계의 침해다.' },
  { s:'s1', t:'국제 규범·GDPR', d:3, q:'다음 〈보기〉에서 GDPR에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 2018년 5월 25일 시행되었으며 회원국에 직접 적용되는 규정(Regulation)이다\nㄴ. EU 역내에 사업장이 없어도 EU 정보주체에게 재화·서비스를 제공하면 적용될 수 있다\nㄷ. 중대한 위반의 과징금 상한은 전 세계 매출액의 4% 또는 2천만 유로 중 낮은 금액이다\nㄹ. 개인정보 유출 시 감독기관 신고 기한은 72시간이다\nㅁ. 적정성 결정과 표준계약조항(SCC)은 6대 적법처리 근거에 포함된다', c:['ㄱ, ㄴ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'과징금은 둘 중 높은 금액이며, 적정성 결정·SCC는 국외이전 수단이지 처리 근거가 아니다.' },
  { s:'s1', t:'국제 규범·GDPR', d:3, q:'다음은 GDPR 7원칙의 설명이다. 원칙과 설명의 연결이 옳지 않은 것은?', c:['목적 제한 — 수집 목적 범위에서만 이용하고 양립 불가능한 목적으로 전용하지 않는다','저장 제한 — 처리 목적 달성에 필요한 기간을 넘겨 보관하지 않는다','무결성·기밀성 — 적절한 보안조치로 무단 접근·훼손·유출을 방지한다','책임성 — 정보주체가 컨트롤러의 원칙 준수 여부를 스스로 입증해야 한다'], a:3, e:'책임성(Accountability)은 컨트롤러가 원칙 준수를 입증할 책임을 지는 원칙이다.' },
  { s:'s1', t:'국제 규범·GDPR', d:3, q:'다음 〈보기〉에서 OECD 프라이버시 8원칙에 해당하는 것을 모두 고른 것은?\n\nㄱ. 수집 제한\nㄴ. 목적 명확화\nㄷ. 정보주체 참여\nㄹ. 익명·가명 처리 노력\nㅁ. 피해 예방(Preventing Harm)', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄷ, ㅁ'], a:0, e:'익명·가명 처리 노력은 국내 8원칙, 피해 예방은 APEC 9원칙의 제1원칙이다.' },
  { s:'s1', t:'국제 규범·GDPR', d:3, q:'개인정보보호 원칙 체계와 그 특징을 연결한 것으로 옳은 것은?', c:['OECD 8원칙 — 두음 합·목·최·정·저·무·책 / 고유 항목은 책임성','GDPR 7원칙 — 두음 수·정·목·이·안·공·참·책 / 고유 항목은 정보주체 참여','국내 개인정보보호법 8원칙 — 두음 수·필·정·기·안·공·정·익 / 고유 항목은 익명·가명 처리 노력','APEC 9원칙 — 두음 식·보·탐·대·복 / 고유 항목은 피해 예방'], a:2, e:'OECD는 수정목이안공참책, GDPR은 합목최정저무책, 식보탐대복은 NIST CSF다.' },
  { s:'s1', t:'국제 규범·GDPR', d:3, q:'다음은 Privacy by Design 7원칙을 적용한 설계 방안이다. 원칙에 어긋나는 것은?', c:['서비스 최초 가입 시 마케팅 수신 항목을 기본 미동의 상태로 둔다','개인정보 처리 흐름을 설계 단계에서 문서화하고 영향평가를 사전에 수행한다','보안을 강화하기 위해 이용자 편의 기능을 대폭 축소하는 것을 당연한 전제로 삼는다','수집부터 파기까지 전 생애주기에 걸쳐 보호조치를 적용한다'], a:2, e:'PbD 제4원칙은 포지티브섬으로, 프라이버시와 기능을 모두 달성하는 것을 지향한다.' },
  { s:'s1', t:'국제 규범·GDPR', d:3, q:'다음 사례에 대한 설명으로 가장 옳은 것은?\n\n국내에 본사를 둔 D사는 EU 거주자를 대상으로 온라인 쇼핑몰을 운영하며,\nEU 이용자의 결제·배송 정보를 국내 서버에 저장한다.\nD사는 EU에 사업장이나 지점을 두고 있지 않다.', c:['EU에 사업장이 없으므로 GDPR은 적용되지 않는다','EU 정보주체에게 재화를 제공하므로 GDPR이 역외 적용될 수 있고, 위반 시 전 세계 매출 기준 과징금이 부과될 수 있다','GDPR은 적용되지만 과징금은 EU 역내 매출에만 부과된다','정보주체의 동의를 받으면 GDPR 적용이 면제된다'], a:1, e:'GDPR은 역외 적용되며 과징금 산정 기준은 전 세계 매출액이다.' },
  { s:'s1', t:'국제 규범·GDPR', d:2, q:'각국 개인정보보호 제도에 대한 설명으로 옳지 않은 것은?', c:['중국은 2021년 개인정보보호법(PIPL)을 시행하며 국외이전 통제를 강화했다','일본은 개인정보보호법(APPI)을 두고 개인정보보호위원회(PPC)가 감독한다','미국은 EU와 같은 포괄적 단일법을 두고 연방 차원에서 통합 규율한다','EU는 GDPR을 통해 옵트인 중심의 강력한 정보주체 권리 체계를 두고 있다'], a:2, e:'미국은 포괄법 없이 HIPAA·COPPA·GLBA·CCPA 등 분야별 개별법 중심이다.' },
  { s:'s1', t:'조직·국제표준', d:3, q:'다음 〈보기〉에서 CPO와 DPO에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. CPO는 개인정보보호법상 개인정보 보호책임자를 말한다\nㄴ. CPO를 지정하지 않을 수 있는 경우 사업주 또는 대표자가 CPO가 된다\nㄷ. CPO에 대해서는 불이익 금지와 업무의 독립성 보장이 규정되어 있다\nㄹ. DPO는 GDPR상 데이터보호책임자이며 공공기관 등은 지정 의무가 있다\nㅁ. CPO는 반드시 외부 전문가를 위촉해야 한다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㅁ','ㄴ, ㄷ, ㅁ','ㄱ, ㄹ, ㅁ'], a:0, e:'CPO는 임원 또는 개인정보 처리 관련 부서의 장이 맡으며, 외부 전문가만 가능한 것이 아니다.' },
  { s:'s1', t:'조직·국제표준', d:3, q:'다음 중 CPO의 업무로 법에 규정되어 있지 않은 것은?', c:['개인정보 처리 실태 및 관행의 정기적인 조사 및 개선','개인정보 유출·오용·남용 방지를 위한 내부통제시스템 구축','개인정보 보호 교육 계획의 수립 및 시행','개인정보 침해 사건에 대한 수사와 가해자 처벌'], a:3, e:'수사·처벌은 수사기관과 감독기구의 권한이며 CPO의 법정 업무가 아니다.' },
  { s:'s1', t:'조직·국제표준', d:3, q:'국제표준과 그 용도를 옳게 연결한 것은?', c:['ISO/IEC 29100 — 프라이버시 프레임워크 / ISO/IEC 27701 — PIMS(27001 확장) / ISO 19011 — 감사 표준','ISO/IEC 27018 — PIMS 인증 기준 / ISO/IEC 29100 — 클라우드 PII 보호','ISO/IEC 27701 — 감사 수행 표준 / ISO 19011 — 개인정보 영향평가 가이드','ISO/IEC 27001 — 프라이버시 프레임워크 / ISO/IEC 29134 — ISMS 통제 기준'], a:0, e:'27018은 클라우드 PII 처리자 보호, 29134는 영향평가 가이드다.' },
  { s:'s1', t:'조직·국제표준', d:3, q:'다음 〈보기〉에서 프라이버시 강화기술(PET)과 비식별 지표에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 동형암호는 암호화된 상태에서 연산을 수행할 수 있는 기술이다\nㄴ. 연합학습은 원본 데이터를 중앙에 모으지 않고 모델을 학습·공유한다\nㄷ. K-익명성은 동질집합 내 민감속성이 최소 l개 이상 존재하도록 하는 지표다\nㄹ. T-근접성은 동질집합의 민감속성 분포가 전체 분포와 t 이하로 차이 나도록 한다\nㅁ. 차분 프라이버시는 질의 결과에 잡음을 추가해 개인의 기여를 감춘다', c:['ㄱ, ㄴ, ㄹ, ㅁ','ㄱ, ㄷ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'ㄷ은 L-다양성에 대한 설명이다. K-익명성은 같은 속성 조합이 최소 k명 이상 존재하도록 하는 지표다.' },
  { s:'s1', t:'개인정보 개념', d:3, q:'다음 사례에서 개인정보처리자와 개인정보취급자를 옳게 구분한 것은?\n\nE 쇼핑몰(법인)은 고객 데이터베이스를 운용하며,\n마케팅팀 사원 김OO과 파견계약으로 근무하는 상담원 박OO이\n회사의 지휘·감독을 받아 고객정보를 조회·처리한다.', c:['E 쇼핑몰이 처리자, 김OO·박OO이 취급자다','김OO·박OO이 처리자, E 쇼핑몰이 취급자다','파견근로자인 박OO은 취급자에 해당하지 않는다','법인은 처리자가 될 수 없고 대표이사 개인이 처리자다'], a:0, e:'처리자는 업무 목적으로 개인정보파일을 운용하는 법인·단체·개인이고, 취급자는 지휘·감독을 받아 처리하는 자연인으로 파견·시간제 근로자를 포함한다.' },
  { s:'s1', t:'개인정보 개념', d:2, q:'다음 중 개인정보보호법의 보호 범위에 대한 설명으로 옳은 것은?', c:['전자적으로 처리되는 개인정보만 보호 대상이다','수기로 작성된 종이 문서상의 개인정보도 보호 대상이다','공공기관이 보유한 개인정보만 보호 대상이다','법인의 대표자 이름은 언제나 보호 대상에서 제외된다'], a:1, e:'2011년 제정의 의의 중 하나가 전자적 처리 정보에서 수기문서까지 보호 대상을 확대한 것이다.' },
  { s:'s1', t:'프라이버시·특성', d:2, q:'개인정보 유출 사고가 기업에 미치는 영향에 대한 설명으로 옳지 않은 것은?', c:['안전조치 의무 위반으로 인한 유출은 전체 매출액 기준 과징금 대상이 될 수 있다','고의 또는 중대한 과실로 인한 유출은 징벌적 손해배상 대상이 될 수 있다','ISMS-P 인증을 보유하고 있으면 법상 안전조치 의무가 면제된다','피해자는 손해액을 입증하지 않고도 법정 손해배상을 청구할 수 있다'], a:2, e:'인증 보유는 법상 의무 이행을 대체하지 않는다.' },
  { s:'s1', t:'조직·국제표준', d:3, q:'다음 〈보기〉에서 국내대리인 제도에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 국내에 주소 또는 영업소가 없는 개인정보처리자 중 일정 기준에 해당하면 지정한다\nㄴ. 국내대리인은 국내에서의 통지·공지 수신과 자료 제출 응대 등을 담당한다\nㄷ. 국내대리인의 성명·주소·연락처 등은 개인정보 처리방침에 포함해 공개한다\nㄹ. 모든 국내 중소기업도 국내대리인을 지정해야 한다\nㅁ. 국내대리인 지정은 구두 합의만으로 가능하다', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄹ, ㅁ','ㄴ, ㄷ, ㅁ','ㄱ, ㄴ, ㄹ'], a:0, e:'국내대리인은 국내에 주소·영업소가 없는 사업자의 의무이며 문서로 지정한다.' }
);
/* ───── 2과목 · 지문형·조합형 보강 ───── */
CPPG.mcq.push(
  { s:'s2', t:'법체계·원칙', d:3, q:'다음 〈보기〉에서 개인정보보호법과 다른 법률의 관계에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 개인정보 보호에 관하여 다른 법률에 특별한 규정이 있으면 그 법률이 우선한다\nㄴ. 특별법이 규정하지 않은 사항에는 개인정보보호법이 보충적으로 적용된다\nㄷ. 개인정보보호법은 사업장 내부 임직원의 개인정보에는 적용되지 않는다\nㄹ. 신용정보법·의료법·위치정보법은 개인정보보호법에 대한 특별법의 예다\nㅁ. 고시나 지침이 법률과 다르면 고시가 우선한다', c:['ㄱ, ㄴ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄷ, ㄹ'], a:0, e:'개인정보보호법은 임직원의 개인정보에도 적용되고, 법령 위계상 법률이 고시보다 우선한다.' },
  { s:'s2', t:'법체계·원칙', d:3, q:'다음은 개인정보보호법 제정 배경에 관한 설명이다. 옳지 않은 것은?', c:['제정 전에는 정보통신망법·공공기관 개인정보보호법·신용정보보호법으로 분산되어 오프라인 사업자가 사각지대에 있었다','제정으로 규율 대상이 약 51만개에서 약 350만개 수준으로 확대되었다','제정으로 집단분쟁조정과 단체소송이라는 구제수단이 도입되었다','제정 당시에도 전자적으로 처리되는 개인정보만을 보호 대상으로 한정하였다'], a:3, e:'제정의 핵심 의의 중 하나가 수기문서까지 보호 대상을 확대한 것이다.' },
  { s:'s2', t:'법체계·원칙', d:3, q:'개인정보보호법 제3조 보호원칙에 대한 설명으로 옳은 것은?', c:['개인정보처리자는 가명처리를 우선하고 가명처리가 불가능한 경우에 익명처리를 하여야 한다','개인정보처리자는 익명처리가 가능한 경우에는 익명에 의하여, 익명처리로 목적을 달성할 수 없는 경우에는 가명에 의하여 처리되도록 하여야 한다','개인정보처리자는 어떤 경우에도 가명처리를 할 수 없다','익명·가명 처리는 GDPR에만 있는 원칙이며 국내법에는 없다'], a:1, e:'법 제3조 제7항은 익명처리 우선, 익명이 불가능하면 가명처리라는 순서를 정하고 있다. 순서를 뒤바꾼 보기가 단골이다.' },
  { s:'s2', t:'법체계·원칙', d:3, q:'다음 〈보기〉에서 개인정보보호법상 보호원칙에 해당하지 않는 것을 모두 고른 것은?\n\nㄱ. 처리 목적을 명확히 하고 그 목적에 필요한 범위에서 최소한의 개인정보를 수집한다\nㄴ. 개인정보의 처리 방법과 종류 등에 따라 사생활 침해를 최소화하는 방법으로 처리한다\nㄷ. 컨트롤러는 원칙 준수 사실을 스스로 입증할 책임을 진다\nㄹ. 처리 목적에 필요한 범위에서 정확성·완전성·최신성을 보장한다\nㅁ. 개인정보의 국외 이전은 어떠한 경우에도 금지된다', c:['ㄱ, ㄴ','ㄷ, ㅁ','ㄴ, ㄹ','ㄱ, ㄷ, ㄹ'], a:1, e:'책임성(입증책임)은 GDPR 7원칙 요소이고, 국외이전은 법정 사유가 있으면 가능하다.' },
  { s:'s2', t:'개정 연혁', d:3, q:'다음 〈보기〉에서 2023년 3월 14일 전면개정(2023.9.15. 시행)의 내용으로 옳은 것을 모두 고른 것은?\n\nㄱ. 정보통신서비스 제공자 등에 대한 특례(제6장)를 삭제하고 일반규정으로 통합했다\nㄴ. 개인정보 유출 통지·신고 기한을 72시간으로 일원화했다\nㄷ. 재위탁 시 위탁자의 동의를 받도록 하는 규정을 신설했다\nㄹ. 1년간 이용하지 않은 이용자의 개인정보를 반드시 파기하도록 하는 규정을 신설했다\nㅁ. 과징금 상한 산정 기준을 관련 매출액으로 변경했다', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄹ, ㅁ','ㄴ, ㄷ, ㅁ','ㄱ, ㄴ, ㄹ'], a:0, e:'1년 미이용 파기 특례는 삭제되었고, 과징금 기준은 관련 매출액에서 전체 매출액으로 바뀌었다.' },
  { s:'s2', t:'개정 연혁', d:3, q:'2020년 2월 4일 개정(데이터 3법)의 핵심 내용으로 옳게 묶인 것은?', c:['가명정보 개념 도입 · 감독기구를 개인정보보호위원회로 일원화 · 정보통신망법 개인정보 규정 이관','전송요구권 신설 · 자동화된 결정 거부권 신설 · 제6장 특례 삭제','과징금 전체 매출액 기준 도입 · 국외이전 중지명령 신설 · 처리방침 평가제 도입','유출 통지 72시간 일원화 · 재위탁 동의 신설 · 이동형 영상기기 규정 신설'], a:0, e:'나머지는 모두 2023년 전면개정의 내용이다.' },
  { s:'s2', t:'개정 연혁', d:3, q:'다음 중 시행일 연결이 옳은 것은?', c:['개인정보보호법 제정 시행 — 2011. 9. 30. / 전면개정 시행 — 2023. 9. 15. / 안전성 확보조치 기준 고시 시행 — 2023. 9. 22.','개인정보보호법 제정 — 2013. 3. 23. / 데이터 3법 시행 — 2018. 5. 25.','전면개정 공포 — 2023. 9. 15. / 시행 — 2024. 9. 15. 전면 적용','안전성 확보조치 기준 고시 시행 — 2020. 8. 5. / 데이터 3법 개정 — 2023. 3. 14.'], a:0, e:'제정은 2011.3.29 공포·2011.9.30 시행, 전면개정은 2023.3.14 공포·2023.9.15 시행, 고시는 2023.9.22 시행이다.' },
  { s:'s2', t:'개정 연혁', d:3, q:'CPPG 시험에서 적용 법령에 관한 설명으로 옳지 않은 것은?', c:['문제는 시험 당일 효력이 있는 법령을 기준으로 출제된다','가이드북·해설서의 서술이 법률과 다르면 법률이 우선한다','아직 시행되지 않은 개정 사항도 공포되었다면 출제 범위에 포함된다','부처명은 시험 당일 시점의 명칭으로 표기된다'], a:2, e:'시행 예정(미시행) 사항은 출제 범위에 포함되지 않는다.' },
  { s:'s2', t:'동의 제도', d:3, q:'다음은 F 서비스의 회원가입 동의 화면이다.\n\n· [필수] 수집·이용 동의, [필수] 마케팅 활용 동의, [필수] 제3자 제공 동의를 각각 분리해 표시\n· 마케팅 활용 동의를 거부하면 가입 절차가 진행되지 않도록 설계\n· 보유기간·제공받는 자 등 중요한 내용은 본문과 동일한 8포인트 크기로 표시\n\n이에 대한 지적으로 옳게 묶인 것은?', c:['선택 항목을 필수로 처리한 점 · 선택 동의 거부 시 서비스 거부한 점 · 중요 내용 표시 기준 미달','동의 항목을 분리했으므로 모두 적법하다','중요 내용 표시만 위반이고 나머지는 적법하다','제3자 제공 동의를 필수로 둔 것만 위반이다'], a:0, e:'마케팅 활용은 선택 사항이며 거부를 이유로 서비스를 거부할 수 없고, 중요 내용은 9포인트 이상으로 구분 표시해야 한다.' },
  { s:'s2', t:'동의 제도', d:3, q:'다음 〈보기〉에서 개인정보 수집·이용에 정보주체의 동의가 필요하지 않은 경우를 모두 고른 것은?\n\nㄱ. 법률에 특별한 규정이 있거나 법령상 의무를 준수하기 위해 불가피한 경우\nㄴ. 정보주체와 체결한 계약을 이행하기 위해 불가피하게 필요한 경우\nㄷ. 신규 상품 홍보 문자를 발송하기 위한 경우\nㄹ. 정보주체가 의식불명으로 급박한 생명·신체의 이익을 위해 필요한 경우\nㅁ. 개인정보처리자의 정당한 이익 달성에 필요하고 정보주체의 권리보다 명백히 우선하는 경우', c:['ㄱ, ㄴ, ㄹ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄷ, ㅁ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'홍보·판매 권유 목적 처리는 별도 동의 대상이다.' },
  { s:'s2', t:'동의 제도', d:3, q:'동의를 받는 방법에 관한 설명으로 옳지 않은 것은?', c:['전화로 동의 내용을 알리고 동의 의사를 확인하는 방법도 인정된다','전자우편을 발송해 동의 의사를 회신받는 방법도 인정된다','홈페이지에 동의 내용을 게시하고 정보주체가 동의 여부를 표시하게 할 수 있다','정보주체가 아무 의사표시를 하지 않으면 동의한 것으로 간주할 수 있다'], a:3, e:'침묵·미표시·사전 체크는 유효한 동의가 아니다. 동의는 명확히 표시된 의사표시여야 한다.' },
  { s:'s2', t:'동의 제도', d:3, q:'다음 사례에서 위반 사항으로 옳게 묶인 것은?\n\nG 온라인 학습 서비스는 만 13세 아동의 가입을 받으면서\n· 아동에게 직접 동의를 받고 법정대리인 확인 절차를 생략했다\n· 법정대리인 확인을 위해 부모의 성명·연락처 외에 직장명과 연소득을 함께 받았다\n· 성인용 약관과 동일한 문장으로 고지문을 제시했다', c:['법정대리인 동의 누락 · 최소한의 정보를 넘는 수집 · 아동이 이해하기 쉬운 언어 미사용','법정대리인 동의 누락만 위반이다','최소 정보 초과 수집만 위반이다','만 13세는 아동 규정 적용 대상이 아니므로 위반이 없다'], a:0, e:'만 14세 미만은 법정대리인 동의가 필수이며, 확인에 필요한 최소한의 정보만 수집하고 알기 쉬운 언어로 고지해야 한다.' },
  { s:'s2', t:'동의 제도', d:2, q:'만 14세 미만 아동의 개인정보 처리에 대한 설명으로 옳지 않은 것은?', c:['법정대리인의 동의를 받아야 한다','법정대리인의 동의를 받기 위해 필요한 최소한의 정보는 아동에게서 직접 수집할 수 있다','법정대리인이 동의하지 않으면 수집한 법정대리인의 정보는 계속 보관해도 된다','법정대리인은 아동을 대신해 열람·정정·삭제·처리정지를 요구할 수 있다'], a:2, e:'동의 획득 목적으로만 사용하고, 회신이 없거나 미동의 시에는 파기해야 한다.' },
  { s:'s2', t:'CCTV·처리방침', d:3, q:'다음 〈보기〉에서 고정형 영상정보처리기기의 설치·운영이 허용되는 사유를 모두 고른 것은?\n\nㄱ. 법령에서 구체적으로 허용하고 있는 경우\nㄴ. 범죄의 예방 및 수사를 위하여 필요한 경우\nㄷ. 시설의 안전 및 관리, 화재 예방을 위하여 정당한 권한 범위에서 필요한 경우\nㄹ. 직원의 근무 태도를 상시 감시하기 위한 경우\nㅁ. 교통정보의 수집·분석 및 제공을 위하여 필요한 경우', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ, ㅁ'], a:0, e:'근무 태도 감시는 허용 사유가 아니다. 허용 사유는 법령·범죄 예방수사·시설안전화재예방·교통단속·교통정보·저장하지 않는 경우다.' },
  { s:'s2', t:'CCTV·처리방침', d:3, q:'다음 사례에서 위반 사항으로 옳게 묶인 것은?\n\nH 어린이집은 시설 안전을 이유로 CCTV를 설치하면서\n· 보육실과 함께 교사 탈의실에도 카메라를 설치했다\n· 안내판에는 "CCTV 작동 중"이라고만 표시했다\n· 학부모 민원 대응을 위해 녹음 기능을 켜 두었다\n· 원장이 필요할 때마다 카메라 방향을 임의로 돌려 촬영했다', c:['탈의실 설치 · 안내판 기재사항 누락 · 녹음 기능 사용 · 임의 조작','탈의실 설치와 녹음 기능만 위반이다','안내판 기재사항 누락만 위반이다','시설 안전 목적이므로 위반 사항이 없다'], a:0, e:'사생활 침해 우려 장소 설치 금지, 안내판 4항목 기재, 녹음 금지, 임의 조작·다른 곳 촬영 금지가 모두 적용된다.' },
  { s:'s2', t:'CCTV·처리방침', d:3, q:'이동형 영상정보처리기기에 대한 설명으로 옳은 것은?', c:['업무를 목적으로 하는 촬영은 아무런 근거 없이 자유롭게 할 수 있다','착용형·휴대형·부착거치형으로 구분되며 드론이나 차량에 부착한 기기도 포함된다','촬영 사실은 반드시 안내판으로만 표시해야 한다','이동형 기기에는 녹음 기능 제한이 적용되지 않는다'], a:1, e:'업무 목적 촬영은 원칙적으로 제외되어 동의·계약 이행 등 근거가 필요하고, 표시는 불빛·소리 등으로도 가능하다.' },
  { s:'s2', t:'CCTV·처리방침', d:3, q:'다음 〈보기〉에서 개인정보 처리방침에 포함해야 할 사항을 모두 고른 것은?\n\nㄱ. 개인정보의 처리 목적과 처리·보유 기간\nㄴ. 개인정보 파기 절차 및 방법(보존하는 경우 보존 근거와 보존 항목 포함)\nㄷ. 민감정보의 공개 가능성 및 비공개를 선택하는 방법\nㄹ. 개인정보 보호책임자의 성명 또는 부서 명칭과 연락처\nㅁ. 임직원 성과급 지급 기준과 조직도', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㅁ','ㄷ, ㄹ, ㅁ','ㄱ, ㄷ, ㅁ'], a:0, e:'민감정보 공개 가능성·비공개 선택 방법은 2023년 신설 항목이며, 임직원 성과급 기준은 처리방침 항목이 아니다.' },
  { s:'s2', t:'CCTV·처리방침', d:3, q:'개인정보 처리방침에 대한 설명으로 옳은 것은?', c:['처리방침의 내용과 계약 내용이 다르면 계약 내용이 언제나 우선한다','처리방침은 약관규제법상 약관에 해당하므로 약관 심사 대상이다','처리방침은 인터넷 홈페이지에 지속적으로 게재하는 것이 원칙이며, 불가능하면 사업장 게시·관보 게재 등 법정 방법 중 하나 이상을 택한다','처리방침은 정보주체가 요구할 때만 공개하면 된다'], a:2, e:'처리방침과 계약 내용이 다르면 정보주체에게 유리한 것을 적용하며, 약관으로 보기 어렵다.' },
  { s:'s2', t:'CCTV·처리방침', d:3, q:'개인정보 처리방침 평가제(법 제30조의2)에 대한 설명으로 옳지 않은 것은?', c:['개인정보 보호위원회가 처리방침의 적정성 등을 평가한다','평가 결과가 우수하면 과징금·과태료 감경 등 인센티브를 받을 수 있다','평가 대상은 처리하는 개인정보의 유형·규모 등을 고려해 선정한다','처리방침 작성·공개 의무와 평가 제도는 동일한 조문에 규정되어 있다'], a:3, e:'작성·공개는 제30조, 평가·개선권고는 제30조의2로 별개 조문이다.' },
  { s:'s2', t:'CCTV·처리방침', d:3, q:'다음 사례에 대한 설명으로 옳은 것은?\n\nI 구청은 민원 상담용 개인정보파일을 새로 운용하려 하고,\nJ 온라인 쇼핑몰은 회원 데이터베이스를 운용하고 있으며,\nK 대학병원은 환자 진료기록 파일을 운용하고 있다.\n(J는 민간 기업, I는 공공기관, K는 학교법인 산하 민간 병원이다)', c:['세 기관 모두 개인정보 보호위원회에 개인정보파일을 등록해야 한다','공공기관인 I 구청만 등록 의무가 있다','민간인 J와 K는 KISA에 등록해야 한다','개인정보파일 등록은 모두 자율 사항이다'], a:1, e:'개인정보파일 등록·공개 의무는 공공기관에 한한다.' },
  { s:'s2', t:'CCTV·처리방침', d:3, q:'개인정보 이용·제공 내역 통지(법 제20조의2) 대상으로 옳은 것은?', c:['5만명 이상의 민감정보 또는 고유식별정보를 처리하는 자, 또는 100만명 이상의 개인정보를 처리하는 자','1천명 이상의 개인정보를 처리하는 모든 자','공공기관에 한하여 적용된다','정보주체가 요구한 경우에만 적용된다'], a:0, e:'1천명은 유출 신고 기준이다. 통지 주기는 연 1회 이상이다.' },
  { s:'s2', t:'조직·책임자', d:3, q:'다음 〈보기〉에서 개인정보 보호책임자(CPO)에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 대통령령으로 정하는 기준에 해당하면 CPO를 지정하지 않을 수 있다\nㄴ. CPO를 지정하지 않은 경우 사업주 또는 대표자가 CPO가 된다\nㄷ. CPO는 업무 수행과 관련하여 불이익을 받지 않도록 하고 독립성을 보장해야 한다\nㄹ. CPO는 위반 사실을 알게 되면 즉시 개선조치를 하고 필요하면 대표자에게 보고해야 한다\nㅁ. CPO를 지정하지 않으면 그 조직에는 개인정보 보호 책임자가 존재하지 않는다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'미지정 시 사업주·대표자가 CPO가 되므로 책임자가 없는 상태는 생기지 않는다.' },
  { s:'s2', t:'유출 통지·신고', d:3, q:'다음 사례에서 L사가 취해야 할 조치로 가장 옳은 것은?\n\nL사는 해킹으로 회원 620명의 이름·연락처와 함께 건강 관련 상담 이력이\n외부로 유출된 사실을 인지했다. 유출 경로는 아직 확인 중이다.', c:['1천명 미만이므로 정보주체 통지도 기관 신고도 필요 없다','정보주체에게 72시간 이내 통지해야 하며, 민감정보 유출이자 외부 불법접근이므로 인원과 무관하게 신고 대상이다','정보주체 통지만 하면 되고 기관 신고 대상은 아니다','유출 경로가 확인된 뒤에 통지·신고하면 된다'], a:1, e:'신고 대상은 1천명 이상, 민감정보·고유식별정보 유출, 외부 불법접근에 의한 유출 중 하나에 해당하면 된다.' },
  { s:'s2', t:'유출 통지·신고', d:3, q:'다음 〈보기〉에서 개인정보 유출 통지·신고에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 정보주체 통지 기한과 기관 신고 기한은 모두 알게 된 때부터 72시간 이내다\nㄴ. 유출 항목과 시점·경위를 확인하지 못했다면 나머지 사항부터 먼저 통지하고 확인되는 즉시 추가 통지한다\nㄷ. 정보주체의 연락처를 알 수 없는 정당한 사유가 있으면 홈페이지에 30일 이상 게시하는 것으로 갈음할 수 있다\nㄹ. 유출 통지는 1천명 이상이 유출된 경우에만 하면 된다\nㅁ. 유출 경로가 확인되어 회수·삭제로 권익 침해 가능성이 현저히 낮아진 경우에는 신고하지 않을 수 있다', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ, ㅁ'], a:0, e:'통지에는 인원 기준이 없다. 1천명은 신고 기준이다.' },
  { s:'s2', t:'유출 통지·신고', d:3, q:'개인정보 유출 통지 시 정보주체에게 알려야 할 사항에 해당하지 않는 것은?', c:['유출된 개인정보의 항목과 유출된 시점 및 경위','정보주체가 피해를 최소화하기 위해 할 수 있는 방법','개인정보처리자의 대응조치 및 피해 구제절차','유출에 관여한 임직원의 성명과 소속 부서'], a:3, e:'통지 5항목은 항목, 시점·경위, 피해 최소화 방법, 대응조치·구제절차, 신고 접수 담당부서 및 연락처다.' },
  { s:'s2', t:'정보주체 권리·구제', d:3, q:'다음 〈보기〉에서 개인정보 열람 요구를 제한·거절할 수 있는 사유를 모두 고른 것은?\n\nㄱ. 법률에 따라 열람이 금지되거나 제한되는 경우\nㄴ. 다른 사람의 생명·신체를 해할 우려가 있는 경우\nㄷ. 조세의 부과·징수·환급 업무에 중대한 지장을 초래하는 경우\nㄹ. 각급 학교의 성적 평가 또는 입학자 선발 업무에 중대한 지장을 초래하는 경우\nㅁ. 열람 요구 처리에 인력과 비용이 소요된다는 이유가 있는 경우', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㅁ','ㄷ, ㄹ, ㅁ','ㄱ, ㄷ, ㅁ'], a:0, e:'비용·인력 부담은 열람 거절 사유가 아니다.' },
  { s:'s2', t:'정보주체 권리·구제', d:3, q:'정보주체의 정정·삭제 요구에 대한 설명으로 옳은 것은?', c:['열람을 하지 않은 정보주체도 곧바로 정정·삭제를 요구할 수 있다','다른 법령에서 수집 대상으로 명시된 개인정보는 삭제를 요구할 수 없으며 처리자는 그 사유를 알려야 한다','삭제 요구를 받으면 논리적 삭제만 하면 되고 복구 가능성은 문제되지 않는다','처리자는 정정·삭제 요구에 대해 어떠한 증거자료도 요구할 수 없다'], a:1, e:'정정·삭제는 열람한 정보주체가 요구하며, 삭제 시 복구·재생되지 않도록 조치해야 하고 필요 시 증거자료를 요구할 수 있다.' },
  { s:'s2', t:'정보주체 권리·구제', d:3, q:'다음 〈보기〉에서 처리정지 요구를 거절할 수 있는 사유를 모두 고른 것은?\n\nㄱ. 법률에 특별한 규정이 있거나 법령상 의무를 준수하기 위해 불가피한 경우\nㄴ. 다른 사람의 생명·신체를 해할 우려가 있는 경우\nㄷ. 공공기관이 처리하지 않으면 소관 업무를 수행할 수 없는 경우\nㄹ. 계약 이행이 곤란한데 정보주체가 계약 해지 의사를 명확히 밝히지 않은 경우\nㅁ. 처리정지에 따른 시스템 변경 비용이 발생하는 경우', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㅁ','ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㅁ'], a:0, e:'비용 발생은 거절 사유가 아니다. 거절 사유는 법정 4가지다.' },
  { s:'s2', t:'정보주체 권리·구제', d:3, q:'2023년 개정으로 신설·강화된 정보주체의 권리에 대한 설명으로 옳지 않은 것은?', c:['본인이나 다른 개인정보처리자 등에게 개인정보를 전송하도록 요구할 수 있는 권리가 신설되었다','완전히 자동화된 결정이 권리·의무에 중대한 영향을 미치면 이를 거부하거나 설명을 요구할 수 있다','열람 요구권에 사본 발급 요구가 포함되는 것으로 정비되었다','자동화된 결정은 어떠한 경우에도 예외 없이 거부할 수 있다'], a:3, e:'동의·법률·계약 등에 근거한 결정에는 거부권이 제한될 수 있다.' },
  { s:'s2', t:'정보주체 권리·구제', d:3, q:'손해배상 제도에 대한 설명으로 옳게 묶인 것은?', c:['징벌적 손해배상은 고의·중과실 요건으로 실손해액의 5배 이내, 법정 손해배상은 300만원 이하이며 피해액 입증이 면제된다','징벌적 손해배상은 300만원 이하, 법정 손해배상은 5배 이내다','두 제도 모두 정보주체가 처리자의 고의·과실을 입증해야 한다','법정 손해배상을 청구하면 일반 손해배상으로 변경할 수 없다'], a:0, e:'일반 손해배상은 처리자가 고의·과실 없음을 입증해야 하고, 사실심 변론 종결 전까지 청구 변경이 가능하다.' },
  { s:'s2', t:'정보주체 권리·구제', d:3, q:'다음 사례에 대한 설명으로 옳은 것은?\n\nM사의 부주의한 설정 오류로 회원 정보가 검색엔진에 노출되었고,\n피해 회원 甲은 정신적 손해를 입었으나 구체적 손해액을 입증하기 어렵다.', c:['甲은 손해액을 입증해야만 배상을 받을 수 있다','甲은 법정 손해배상으로 300만원 이하의 범위에서 배상을 청구할 수 있으며, 이때 M사가 고의·과실 없음을 입증해야 한다','甲은 단체소송을 통해 직접 손해배상을 받을 수 있다','손해배상 청구는 분쟁조정을 거친 경우에만 가능하다'], a:1, e:'법정 손해배상은 피해액 입증을 면제하고 입증책임을 처리자에게 둔다. 단체소송으로는 손해배상을 청구할 수 없다.' },
  { s:'s2', t:'분쟁조정·단체소송', d:3, q:'개인정보 분쟁조정 절차에 대한 설명으로 옳은 것은?', c:['조정안은 신청일로부터 60일 이내에 제시하며, 당사자가 15일 이내에 수락 여부를 알리지 않으면 수락한 것으로 본다','조정안은 30일 이내에 제시하며 15일 내 미회신 시 거부한 것으로 본다','조정이 성립해도 권고적 효력만 있어 강제력이 없다','분쟁조정 신청에는 수수료가 부과된다'], a:0, e:'2023년 개정으로 미회신 시 거부 간주에서 수락 간주로 바뀌었고, 조정 성립은 재판상 화해의 효력을 가지며 신청은 무료다.' },
  { s:'s2', t:'분쟁조정·단체소송', d:3, q:'다음 〈보기〉에서 집단분쟁조정에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 피해를 입은 정보주체의 수가 50명 이상이어야 한다\nㄴ. 사건의 중요한 쟁점이 사실상 또는 법률상 공통되어야 한다\nㄷ. 이미 법원에 소를 제기한 정보주체도 50명 산정에 포함한다\nㄹ. 절차 개시 공고는 14일 이상 하여야 한다\nㅁ. 조정 기간은 공고 종료일의 다음 날부터 60일 이내다', c:['ㄱ, ㄴ, ㄹ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄷ, ㅁ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'합의가 이루어진 자, 다른 분쟁조정기구에서 절차가 진행 중인 자, 소를 제기한 자는 산정에서 제외된다.' },
  { s:'s2', t:'분쟁조정·단체소송', d:3, q:'개인정보 단체소송에 대한 설명으로 옳지 않은 것은?', c:['집단분쟁조정을 거부하거나 조정 결과를 수락하지 않은 경우에 제기할 수 있다','권리침해 행위의 금지·중지를 구하는 청구를 할 수 있다','손해배상과 원상회복까지 함께 청구할 수 있다','원고는 변호사를 소송대리인으로 선임하여야 한다'], a:2, e:'단체소송의 청구 범위는 금지·중지 청구로 한정되며 손해배상은 포함되지 않는다.' },
  { s:'s2', t:'분쟁조정·단체소송', d:3, q:'다음 〈보기〉에서 단체소송의 원고적격 요건으로 옳은 것을 모두 고른 것은?\n\nㄱ. 소비자단체는 공정거래위원회에 등록하고 정회원수가 1천명 이상이어야 한다\nㄴ. 소비자단체는 등록 후 3년이 경과하여야 한다\nㄷ. 비영리민간단체는 동일한 침해를 입은 100인 이상 정보주체의 소제기 요청이 있어야 한다\nㄹ. 비영리민간단체는 상시 구성원수가 5천명 이상이어야 한다\nㅁ. 비영리민간단체는 설립 후 1년 이상 활동실적이 있으면 된다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'비영리민간단체는 최근 3년 이상 활동실적이 필요하다.' },
  { s:'s2', t:'분쟁조정·단체소송', d:3, q:'개인정보 단체소송의 소송 절차에 대한 설명으로 옳은 것은?', c:['전속관할은 피고의 주된 사무소·영업소 소재지 지방법원 본원 합의부다','전속관할은 원고 단체의 주소지 지방법원이다','원고와 피고 모두 변호사를 소송대리인으로 선임해야 한다','청구 기각 판결이 확정되어도 다른 단체는 언제든 동일한 소를 제기할 수 있다'], a:0, e:'편면적 변호사강제주의로 원고만 변호사 선임이 강제되며, 기각 확정 시 원칙적으로 다른 단체는 제소할 수 없다(예외 2가지).' },
  { s:'s2', t:'감독기구·제재', d:3, q:'개인정보 보호위원회에 대한 설명으로 옳게 묶인 것은?', c:['국무총리 소속 중앙행정기관 · 위원장 포함 9명 · 위원 임기 3년(1차 연임 가능) · 시정명령과 과징금 부과 권한 보유','대통령 소속 자문기구 · 위원 15명 · 임기 5년 · 권고 권한만 보유','행정안전부 소속 심의기구 · 위원 7명 · 임기 2년 · 조사 권한 없음','국무총리 소속 · 위원 9명 · 임기 3년 · 과징금은 부과할 수 없고 시정명령만 가능'], a:0, e:'2020년 개정으로 독립 감독기구가 되었고 조사·처분 권한을 가진다.' },
  { s:'s2', t:'감독기구·제재', d:3, q:'다음 〈보기〉에서 위반행위와 제재의 연결이 옳은 것을 모두 고른 것은?\n\nㄱ. 안전조치 의무를 위반해 개인정보가 유출된 경우 — 전체 매출액의 3% 이하 과징금\nㄴ. 가명정보를 특정 개인을 알아보기 위해 처리한 경우 — 3년 이하 징역 또는 3천만원 이하 벌금\nㄷ. 개인정보 처리방침을 공개하지 않은 경우 — 5년 이하 징역\nㄹ. 손해배상책임 보장 의무를 이행하지 않은 경우 — 2천만원 이하 과태료\nㅁ. 거짓이나 부정한 수단으로 개인정보를 취득한 경우 — 과태료 1천만원', c:['ㄱ, ㄴ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'처리방침 미공개는 과태료 대상이고, 부정한 수단에 의한 취득은 5년 이하 징역 또는 5천만원 이하 벌금이다.' },
  { s:'s2', t:'감독기구·제재', d:3, q:'2023년 개정에 따른 과징금 제도에 대한 설명으로 옳은 것은?', c:['상한액 기준이 관련 매출액에서 전체 매출액으로 변경되었고, 위반행위와 관련 없는 매출액은 제외할 수 있다','상한액 기준이 전체 매출액에서 관련 매출액으로 완화되었다','과징금은 민간 사업자에게만 부과되고 공공기관과 수탁자는 대상이 아니다','과징금 납부기한 연기나 분할납부는 허용되지 않는다'], a:0, e:'적용 대상이 공공기관을 포함한 모든 처리자와 수탁자로 확대되었고, 중소·영세사업자는 2년 범위에서 납부기한 연기·분할납부가 가능하다.' },
  { s:'s2', t:'감독기구·제재', d:2, q:'다음 중 개인정보 보호 관련 기관의 역할 연결이 옳지 않은 것은?', c:['개인정보 보호위원회 — 법 집행·조사·처분 및 정책 총괄','한국인터넷진흥원(KISA) — 유출 신고 접수 및 ISMS-P 인증·심사 수행','개인정보 분쟁조정위원회 — 분쟁조정 및 집단분쟁조정 수행','과학기술정보통신부 — 개인정보 분쟁조정 결과에 대한 최종 심판'], a:3, e:'과기정통부는 ISMS-P를 공동 주관하며 분쟁조정 심판 기능은 없다.' },
  { s:'s2', t:'감독기구·제재', d:2, q:'개인정보 보호 인증·자율규제에 대한 설명으로 옳지 않은 것은?', c:['ePRIVACY·ePRIVACY PLUS는 민간 인증 마크다','CBPR은 APEC의 국경 간 프라이버시 규칙 인증 체계다','자율규제 규약을 준수하면 법 위반에 대한 책임이 면제된다','ISMS-P는 정보보호와 개인정보보호를 함께 인증하는 제도다'], a:2, e:'자율규제 준수는 법적 책임을 면제하지 않는다.' }
);
/* ───── 3과목 · 지문형·조합형 보강 ───── */
CPPG.mcq.push(
  { s:'s3', t:'수집·이용', d:3, q:'다음 〈보기〉에서 개인정보를 수집·이용할 수 있는 적법 근거에 해당하는 것을 모두 고른 것은?\n\nㄱ. 정보주체의 동의를 받은 경우\nㄴ. 법률에 특별한 규정이 있거나 법령상 의무 준수를 위해 불가피한 경우\nㄷ. 공공기관이 법령 등에서 정하는 소관 업무 수행을 위해 불가피한 경우\nㄹ. 광고 수익을 늘리기 위해 이용자 관심사를 수집하려는 경우\nㅁ. 정보주체와 체결한 계약의 체결·이행을 위해 불가피하게 필요한 경우', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ, ㅁ'], a:0, e:'단순한 수익 증대는 적법 근거가 아니다. 정당한 이익은 정보주체 권리보다 명백히 우선할 때만 인정된다.' },
  { s:'s3', t:'수집·이용', d:3, q:'다음 사례에 대한 지적으로 옳게 묶인 것은?\n\nN 배달앱은 회원가입 시 다음과 같이 정보를 받는다.\n· 서비스 이용에 필요 없는 최종학력과 결혼 여부를 필수 항목으로 수집\n· 동의 거부 시 회원가입 자체가 불가능하도록 설계\n· 동의 화면에 보유·이용 기간을 표시하지 않음', c:['최소 수집 위반 · 필요 최소한 외 정보 미동의를 이유로 한 서비스 거부 · 고지 4사항 중 보유기간 누락','최소 수집 위반만 해당한다','보유기간 누락만 해당한다','동의를 받았으므로 위반 사항이 없다'], a:0, e:'최소 수집 원칙과 그 입증책임은 처리자에게 있고, 고지 4사항은 목적·항목·기간·거부권리다.' },
  { s:'s3', t:'수집·이용', d:2, q:'개인정보 수집 시 정보주체에게 알려야 할 사항(고지 4사항)에 해당하지 않는 것은?', c:['개인정보의 수집·이용 목적','수집하려는 개인정보의 항목','개인정보의 보유 및 이용 기간','개인정보를 처리하는 수탁자의 상호와 대표자 성명'], a:3, e:'고지 4사항은 목적·항목·기간·동의 거부권과 불이익이다. 수탁자 정보는 위탁 시 공개 사항이다.' },
  { s:'s3', t:'수집·이용', d:3, q:'다음 중 간접 수집(정보주체 이외로부터 수집)에 대한 설명으로 옳은 것은?', c:['정보주체가 요구하면 지체 없이 수집 출처, 처리 목적, 처리정지·동의철회 요구권을 알려야 한다','수집 출처는 어떠한 경우에도 알릴 필요가 없다','간접 수집한 개인정보는 5일 이내에 파기해야 한다','간접 수집 사실은 정보주체에게 알리지 않고 처리방침에도 기재하지 않는다'], a:0, e:'일정 규모 이상 처리자는 요구가 없어도 통지해야 하며, 5일은 파기 기한이다.' },
  { s:'s3', t:'수집·이용', d:3, q:'다음 〈보기〉에서 기간 기준의 연결이 옳은 것을 모두 고른 것은?\n\nㄱ. 개인정보 파기 — 사유 발생 시 지체 없이 5일 이내\nㄴ. 간접 수집한 개인정보의 수집 출처 통지 — 제공받은 날부터 3개월 이내\nㄷ. 유출 통지·신고 — 알게 된 때부터 72시간 이내\nㄹ. 이용·제공 내역 통지 — 3년에 1회 이상\nㅁ. 분쟁조정안 제시 — 신청일부터 60일 이내', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ'], a:0, e:'이용·제공 내역 통지는 연 1회 이상이다.' },
  { s:'s3', t:'수집·이용', d:3, q:'다음 〈보기〉에서 목적 외 이용·제공이 허용되는 경우를 모두 고른 것은?\n\nㄱ. 정보주체로부터 별도의 동의를 받은 경우\nㄴ. 다른 법률에 특별한 규정이 있는 경우\nㄷ. 통계작성 및 학술연구 등을 위해 특정 개인을 알아볼 수 없는 형태로 제공하는 경우\nㄹ. 범죄의 수사와 공소의 제기·유지를 위해 필요한 경우\nㅁ. 신규 서비스 홍보를 활성화하기 위해 필요한 경우', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'마케팅·홍보 활성화는 목적 외 이용의 예외 사유가 아니다.' },
  { s:'s3', t:'수집·이용', d:3, q:'공공기관이 개인정보를 목적 외로 이용하거나 제3자에게 제공하는 경우의 의무로 옳은 것은?', c:['이용·제공의 법적 근거와 목적·범위 등을 관보 또는 인터넷 홈페이지에 게재해야 한다','별도의 공개 절차 없이 내부 결재만으로 처리할 수 있다','정보주체 전원의 서면 동의를 받아야만 한다','제공받는 자에게는 어떠한 제한도 요구할 수 없다'], a:0, e:'공공기관은 게재 의무가 있고, 제공받는 자에게 목적·방법 제한과 안전성 확보조치를 요구할 수 있다.' },
  { s:'s3', t:'수집·이용', d:3, q:'다음 사례에서 마케팅 활용을 위해 필요한 조치를 옳게 묶은 것은?\n\nO 쇼핑몰은 회원 데이터를 이용해\n· 신규 상품 추천 문자를 발송하고\n· 문자 발송 업무를 외부 대행사에 맡기려 한다', c:['홍보·판매 권유 목적의 별도 동의 · 광고성 정보 수신 동의와 (광고) 표기 · 홍보 업무 위탁 사실의 정보주체 통지','수집·이용 동의 하나만 받으면 모두 가능하다','위탁 사실은 공개도 통지도 필요 없다','광고성 정보 전송은 개인정보보호법만 적용되고 정보통신망법은 적용되지 않는다'], a:0, e:'개인정보 처리 동의(법 §22④)와 광고 전송 동의(정보통신망법 §50)는 별개이며, 홍보·판매권유 위탁은 통지까지 필요하다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'다음 사례를 위탁과 제3자 제공으로 옳게 분류한 것은?\n\n(가) 자사 상품 배송을 위해 택배사에 수령인 정보를 전달\n(나) 제휴 카드사에 회원정보를 제공해 카드사가 자사 상품을 권유\n(다) 콜센터 상담 업무를 외부 업체에 맡김\n(라) 계열사에 회원정보를 제공해 계열사 이벤트를 안내', c:['(가)(다) 위탁 — (나)(라) 제3자 제공','(가)(나) 위탁 — (다)(라) 제3자 제공','(가)(다)(라) 위탁 — (나) 제3자 제공','네 경우 모두 제3자 제공'], a:0, e:'판단 기준은 누구의 목적으로 처리하는가다. 받는 자가 자기 목적으로 쓰면 제3자 제공이다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'다음 〈보기〉에서 위탁과 제3자 제공의 비교로 옳은 것을 모두 고른 것은?\n\nㄱ. 위탁은 위탁자의 목적을 위한 처리이고, 제3자 제공은 받는 자의 목적을 위한 처리다\nㄴ. 위탁은 원칙적으로 동의가 필요 없고 공개로 갈음할 수 있다\nㄷ. 제3자 제공은 별도 동의와 5가지 사항의 고지가 필요하다\nㄹ. 위탁의 경우 수탁자의 위반에 대해 위탁자는 아무런 책임을 지지 않는다\nㅁ. 수탁자는 제3자에 해당하지 않는다', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ'], a:0, e:'수탁자의 위반으로 손해가 발생하면 수탁자를 위탁자의 소속 직원으로 보아 위탁자가 배상 책임을 진다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'다음 〈보기〉에서 개인정보 처리 위탁 계약 문서에 포함해야 할 사항을 모두 고른 것은?\n\nㄱ. 위탁업무 수행 목적 외 개인정보 처리 금지\nㄴ. 개인정보의 기술적·관리적 보호조치\nㄷ. 재위탁 제한에 관한 사항\nㄹ. 수탁자의 최근 3년간 재무제표와 신용등급\nㅁ. 위탁업무와 관련하여 보유하고 있는 개인정보의 관리 현황 점검 등 감독', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ, ㅁ'], a:0, e:'두음 목·제·기·관·손 — 재무 정보는 필수 기재사항이 아니다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'다음 사례에 대한 지적으로 옳게 묶인 것은?\n\nP사는 고객 상담 업무를 Q사에 위탁하면서\n· 계약서 없이 구두로 업무 범위를 합의했고\n· Q사가 업무량 증가를 이유로 R사에 재위탁했으나 P사에 알리지 않았으며\n· 위탁 사실을 홈페이지에 공개하지 않았다', c:['문서 미체결 · 위탁자 동의 없는 재위탁 · 위탁 사실 미공개','재위탁만 위반이다','위탁 사실 미공개만 위반이다','위탁은 동의가 필요 없으므로 위반 사항이 없다'], a:0, e:'위탁은 문서로 해야 하고, 재위탁은 위탁자의 동의가 필요하며, 위탁 사실은 홈페이지에 지속적으로 공개해야 한다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'위탁자의 의무에 대한 설명으로 옳지 않은 것은?', c:['수탁자에게 개인정보 보호 교육을 실시해야 한다','수탁자가 개인정보를 안전하게 처리하는지 감독해야 한다','위탁하는 업무의 내용과 수탁자를 인터넷 홈페이지 등에 공개해야 한다','재화·서비스 홍보나 판매 권유 업무를 위탁하는 경우에도 공개만 하면 되고 별도 통지는 필요 없다'], a:3, e:'홍보·판매 권유 업무 위탁은 정보주체에게 알려야(통지) 한다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'제3자 제공 시 정보주체에게 알려야 할 5가지 사항에 해당하지 않는 것은?', c:['개인정보를 제공받는 자','제공받는 자의 개인정보 이용 목적','제공하는 개인정보의 항목','제공받는 자의 개인정보 보호책임자 자격증 보유 여부'], a:3, e:'5사항은 받는 자, 이용 목적, 항목, 보유·이용 기간, 동의 거부권과 불이익이다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'2023년 개정에서 위탁 관련으로 신설·변경된 내용으로 옳게 묶인 것은?', c:['수탁자의 범위에 재위탁받은 제3자를 포함 · 재위탁 시 위탁자의 동의 필요 · 수탁자에게도 주요 조문 준용','재위탁 전면 금지 · 수탁자 제재 면제 · 위탁 계약 구두 허용','위탁 시 정보주체 동의 필요 · 위탁 사실 공개 폐지','수탁자에 대한 교육 의무 폐지 · 감독 의무 폐지'], a:0, e:'2023년 개정으로 수탁자도 과징금·과태료·형벌의 대상이 될 수 있다.' },
  { s:'s3', t:'국외이전·양도', d:3, q:'다음 〈보기〉에서 개인정보를 국외로 이전할 수 있는 근거를 모두 고른 것은?\n\nㄱ. 정보주체로부터 국외 이전에 관한 별도의 동의를 받은 경우\nㄴ. 법률이나 대한민국을 당사자로 하는 조약에 국외 이전 규정이 있는 경우\nㄷ. 보호위원회가 고시하는 인증을 받은 경우로서 필요한 조치를 한 경우\nㄹ. 계약의 체결·이행을 위해 필요한 경우로서 정보주체에게 알린 경우\nㅁ. 이전받는 국가의 인건비가 저렴한 경우', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'두음 동·법·인·계·공 — 비용 절감은 근거가 되지 않는다.' },
  { s:'s3', t:'국외이전·양도', d:3, q:'개인정보 국외이전 중지명령에 대한 설명으로 옳은 것은?', c:['국외이전이 법을 위반했거나 이전받는 국가의 보호수준이 취약해 피해 우려가 현저한 경우 보호위원회가 이전 중지를 명할 수 있다','국외이전 중지명령 제도는 국내법에 존재하지 않는다','중지명령은 KISA가 발령한다','중지명령을 받아도 이의신청 절차는 없다'], a:0, e:'2023년 개정으로 신설된 제도이며 개인정보 보호위원회가 명령 주체다.' },
  { s:'s3', t:'국외이전·양도', d:3, q:'다음 사례에 대한 설명으로 옳은 것은?\n\nS사는 해외 클라우드에 회원 데이터를 저장하기로 하고\n국외 이전에 관한 별도 동의를 받지 않은 채 이전을 시작했으며,\n계약서에도 이전 국가와 이전받는 자에 관한 내용을 담지 않았다.', c:['국외이전 요건 위반으로 전체 매출액의 3% 이하 과징금 대상이 될 수 있다','국외이전 위반은 과태료 3천만원 대상이다','클라우드 이용은 국외이전에 해당하지 않는다','국내 서버가 아니면 개인정보보호법이 적용되지 않는다'], a:0, e:'과태료 3천만원은 광고성 정보 전송 위반의 제재다.' },
  { s:'s3', t:'국외이전·양도', d:3, q:'영업양도 시 정보주체에게 알려야 할 사항과 양수자의 지위에 대한 설명으로 옳은 것은?', c:['정보주체의 동의를 새로 받아야 이전할 수 있다','이전 사실, 양수자의 연락처, 이전을 원하지 않을 때의 조치 방법·절차를 알려야 한다','양수자는 이전받은 개인정보를 새로운 목적으로 자유롭게 이용할 수 있다','양수자는 개인정보처리자로 보지 않는다'], a:1, e:'영업양도는 동의가 아니라 통지이며, 양수자는 이전 당시의 본래 목적으로만 이용·제공할 수 있고 개인정보처리자로 본다.' },
  { s:'s3', t:'국외이전·양도', d:3, q:'다음 〈보기〉에서 영업양도 통지에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 양도자는 이전 전에 정보주체에게 알려야 한다\nㄴ. 양수자도 지체 없이 알려야 하되 양도자가 이미 알린 경우에는 제외된다\nㄷ. 과실 없이 정보주체에게 알릴 수 없는 경우 홈페이지에 30일 이상 게재할 수 있다\nㄹ. 통지는 구두로만 하여야 한다\nㅁ. 양수자는 원래의 처리자와 동일한 의무를 진다', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ'], a:0, e:'통지는 서면 등의 방법으로 하며, 홈페이지가 없으면 사업장 등에 30일 이상 게시한다.' },
  { s:'s3', t:'보유·파기', d:3, q:'다음 사례에 대한 지적으로 옳게 묶인 것은?\n\nT 쇼핑몰은 회원 탈퇴 처리를 다음과 같이 하고 있다.\n· 탈퇴 즉시 전자상거래법상 보존 의무가 있는 계약·결제 기록까지 모두 삭제\n· 운영 DB에서만 삭제하고 백업본은 그대로 유지\n· 파기 사실을 별도로 기록하지 않음', c:['법령상 보존 대상은 분리 보관해야 함 · 백업본까지 파기해야 함 · 파기 기록을 작성·보관해야 함','법령 보존분 삭제만 문제된다','백업본 유지는 문제되지 않는다','모두 적법한 처리다'], a:0, e:'보존 의무가 있는 정보는 다른 개인정보와 분리하여 저장·관리하고, 파기는 복원 불가능하게 하며 기록을 남겨야 한다.' },
  { s:'s3', t:'보유·파기', d:3, q:'다음 〈보기〉에서 개인정보 파기에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 보유기간 경과·처리 목적 달성 등 사유가 발생하면 지체 없이 5일 이내에 파기한다\nㄴ. 전자적 파일은 복원이 불가능한 방법으로 영구 삭제해야 한다\nㄷ. 종이 문서는 파쇄하거나 소각한다\nㄹ. 다른 법령에 보존 의무가 있어도 예외 없이 파기해야 한다\nㅁ. 일부만 파기할 때는 해당 부분을 복원할 수 없도록 처리한다', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄹ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄹ'], a:0, e:'법령상 보존 의무가 있으면 파기하지 않고 분리 보관한다.' },
  { s:'s3', t:'보유·파기', d:3, q:'다음 중 개인정보의 적법한 파기 방법으로 볼 수 없는 것은?', c:['전자적 파일을 복원이 불가능하도록 영구 삭제','자기장을 이용한 디가우징 또는 저장매체의 물리적 파괴','종이 출력물의 파쇄 또는 소각','파일을 휴지통으로 이동한 뒤 폴더 이름을 변경'], a:3, e:'복원이 가능한 조치는 파기로 인정되지 않는다.' },
  { s:'s3', t:'보유·파기', d:3, q:'다음 중 다른 법령에 따라 보존해야 하는 개인정보의 처리 방법으로 옳은 것은?', c:['다른 개인정보와 분리하여 저장·관리하고 보존 근거와 보존 항목을 처리방침에 기재한다','다른 개인정보와 함께 보관하되 접근권한만 제한한다','보존 의무가 있어도 5일 내에 파기한다','정보주체의 동의를 다시 받아 보관한다'], a:0, e:'분리 보관이 원칙이며 처리방침에 보존 근거·항목을 밝혀야 한다.' },
  { s:'s3', t:'보유·파기', d:2, q:'2023년 개정으로 삭제된 내용에 해당하는 것은?', c:['1년간 서비스를 이용하지 않은 이용자의 개인정보를 파기하도록 한 특례 규정','개인정보 파기 시 복원 불가능한 방법을 사용하도록 한 규정','보유기간 경과 시 지체 없이 파기하도록 한 규정','법령상 보존 의무가 있는 정보를 분리 보관하도록 한 규정'], a:0, e:'옛 정보통신망법 특례의 휴면계정 파기 강제 규정은 2023년 개정으로 삭제되었다.' },
  { s:'s3', t:'광고성 정보', d:3, q:'다음 사례에서 위반 사항으로 옳게 묶인 것은?\n\nU 쇼핑몰의 마케팅 담당자는\n· 수신동의한 회원에게 밤 22시 30분에 할인 안내 문자를 보냈고\n· 3년 전 수신거부한 회원에게 "기간이 지났다"며 다시 발송했으며\n· 문자 제목에 (광고) 표기를 하지 않았고 수신거부 방법도 적지 않았다', c:['야간 전송 위반 · 수신거부자 재전송 위반 · (광고) 표기 및 수신거부 방법 미표시','야간 전송만 위반이다','수신거부자 재전송만 위반이다','수신동의를 받았으므로 위반이 없다'], a:0, e:'21시부터 08시까지는 별도 사전 동의가 필요하고, 수신거부·철회 시에는 기간 제한 없이 전송이 금지된다.' },
  { s:'s3', t:'광고성 정보', d:3, q:'영리목적 광고성 정보 전송에 대한 설명으로 옳은 것은?', c:['수신거부 의사를 표시한 자에게는 2년이 지나면 다시 전송할 수 있다','수신동의를 받은 날부터 2년마다 수신동의 유지 여부를 확인해야 한다','야간 전송 제한 시간대는 22시부터 07시까지다','광고성 정보 전송 위반은 전체 매출액 3% 과징금 대상이다'], a:1, e:'2년은 수신동의 유지 여부 확인 주기이며, 수신거부자에게는 기간 제한 없이 전송할 수 없다. 야간 제한은 21~08시, 제재는 3천만원 이하 과태료다.' },
  { s:'s3', t:'광고성 정보', d:3, q:'다음 〈보기〉에서 광고성 정보 전송 시 지켜야 할 사항을 모두 고른 것은?\n\nㄱ. 사전에 명시적인 수신 동의를 받는다\nㄴ. 제목이 시작되는 부분에 (광고) 표기를 하고 전송자의 명칭과 연락처를 밝힌다\nㄷ. 수신거부 또는 수신동의 철회 방법을 명시한다\nㄹ. 수신거부 의사를 표시한 자에게는 전송을 중단한다\nㅁ. 수신거부 처리는 비용 절감을 위해 분기별로 일괄 처리한다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'수신거부는 즉시 처리해야 하며 일괄 지연 처리는 위반이다.' },
  { s:'s3', t:'가명정보', d:3, q:'다음 〈보기〉에서 가명정보의 결합·반출에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 서로 다른 처리자 간 결합은 보호위원회 등이 지정한 전문기관이 수행한다\nㄴ. 결합 결과물의 반출은 가명 또는 익명 처리 후 전문기관장의 승인을 받아야 한다\nㄷ. 처리자는 필요 시 직접 결합을 수행할 수 있다\nㄹ. 가명정보 처리 시 추가 정보는 별도로 분리하여 보관·관리해야 한다\nㅁ. 가명정보 처리 관련 기록은 파기한 날부터 3년 이상 보관한다', c:['ㄱ, ㄴ, ㄹ, ㅁ','ㄱ, ㄷ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'임의 결합은 금지된다.' },
  { s:'s3', t:'가명정보', d:3, q:'가명정보에 대하여 적용이 배제되는 조항으로 옳은 것은?', c:['개인정보 유출 신고 의무','개인정보 유출 통지(제34조 제1항)','안전성 확보조치 의무','재식별 금지 의무'], a:1, e:'제28조의7은 정보주체 권리 관련 조항과 제34조 제1항(통지)의 적용을 배제하지만, 신고 의무는 그대로 적용된다.' },
  { s:'s3', t:'가명정보', d:3, q:'다음 사례에 대한 설명으로 옳은 것은?\n\nV 연구소는 가명정보를 분석하던 중 특정 개인을 알아볼 수 있는 정보가\n생성된 사실을 발견했으나, 연구가 끝날 때까지 그대로 두기로 했다.', c:['연구 목적이므로 그대로 두어도 무방하다','즉시 처리를 중지하고 지체 없이 회수·파기해야 하며, 위반 시 형사처벌 대상이 될 수 있다','보호위원회에 신고만 하면 계속 처리할 수 있다','정보주체의 동의를 받으면 재식별 상태로 처리할 수 있다'], a:1, e:'재식별 금지 위반은 3년 이하 징역 또는 3천만원 이하 벌금 대상이다.' },
  { s:'s3', t:'처리 제한', d:3, q:'다음 〈보기〉에서 민감정보 처리에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 다른 개인정보의 처리에 대한 동의와 구분하여 별도로 동의를 받아야 한다\nㄴ. 법령에서 민감정보의 처리를 요구하거나 허용하는 경우에도 처리할 수 있다\nㄷ. 민감정보를 처리하는 경우 안전성 확보에 필요한 조치를 해야 한다\nㄹ. 재화·서비스 제공 과정에서 공개되는 정보에 민감정보가 포함되어 사생활 침해 위험이 있으면 공개 가능성과 비공개 선택 방법을 알려야 한다\nㅁ. 민감정보는 정보주체의 일반적인 수집·이용 동의만으로 처리할 수 있다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'민감정보는 별도 동의 또는 법령 근거 두 경우에만 처리할 수 있다.' },
  { s:'s3', t:'처리 제한', d:3, q:'주민등록번호의 처리 근거와 안전조치에 대한 설명으로 옳은 것은?', c:['법률·대통령령·국회규칙·대법원규칙 등에서 구체적으로 요구·허용한 경우 처리할 수 있다','정보주체의 별도 동의를 받으면 처리할 수 있다','다른 고유식별정보와 동일한 요건으로 처리할 수 있다','내부망에 저장하는 경우 위험도 분석 결과에 따라 암호화를 생략할 수 있다'], a:0, e:'주민등록번호는 동의로 처리할 수 없고 예외 없이 암호화해야 한다.' },
  { s:'s3', t:'영상정보', d:3, q:'다음 〈보기〉에서 고정형 영상정보처리기기 운영자의 의무로 옳은 것을 모두 고른 것은?\n\nㄱ. 설치 목적과 장소, 촬영 범위와 시간, 관리책임자 연락처 등을 안내판에 표시한다\nㄴ. 녹음 기능은 사용할 수 없다\nㄷ. 설치 목적과 다른 목적으로 임의 조작하거나 다른 곳을 비추어서는 안 된다\nㄹ. 영상정보처리기기 운영·관리 방침을 마련해야 하며 처리방침으로 갈음할 수 있다\nㅁ. 개인정보처리자가 아니면 규제 대상이 아니다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'고정형 기기 규제는 공개된 장소에 설치·운영하는 모든 자에게 적용된다.' },
  { s:'s3', t:'영상정보', d:3, q:'영상정보처리기기의 분류에 대한 설명으로 옳은 것은?', c:['고정형에는 폐쇄회로 텔레비전과 네트워크 카메라가 포함된다','착용형 기기는 고정형으로 분류된다','드론에 부착한 카메라는 고정형에 해당한다','네트워크 카메라는 이동형으로 분류된다'], a:0, e:'이동형은 착용형·휴대형·부착거치형(차량·드론 등)으로 구분된다.' },
  { s:'s3', t:'제공·위탁', d:2, q:'다음 중 개인정보 제공과 관련한 설명으로 옳지 않은 것은?', c:['제공받는 자는 제공받은 목적 외의 용도로 이용하거나 다시 제공할 수 없다','제3자 제공 시 고지 사항이 변경되면 다시 알리고 동의를 받아야 한다','수탁자는 제3자에 해당하므로 위탁에도 별도 동의가 필요하다','위탁 사실은 인터넷 홈페이지에 지속적으로 공개해야 한다'], a:2, e:'수탁자는 제3자에 해당하지 않으며 위탁은 동의가 아니라 공개로 갈음한다.' },
  { s:'s3', t:'수집·이용', d:3, q:'다음 사례에서 W사의 처리가 적법하려면 필요한 조치로 가장 옳은 것은?\n\nW사는 서비스 가입 시 수집한 연락처를 이용해\n제휴 보험사의 신규 보험 상품을 안내하는 문자를 발송하려 한다.\n제휴 보험사는 자사 상품 판매를 위해 회원 연락처를 직접 활용한다.', c:['제3자 제공에 대한 별도 동의와 5사항 고지, 광고 전송에 대한 수신 동의가 필요하다','위탁 사실 공개만 하면 된다','수집·이용 동의만으로 가능하다','정보주체에게 사후에 알리기만 하면 된다'], a:0, e:'받는 자가 자기 목적으로 처리하므로 제3자 제공이며, 광고 전송에는 정보통신망법상 수신 동의가 필요하다.' },
  { s:'s3', t:'보유·파기', d:3, q:'다음 중 전자상거래 등에서의 소비자보호에 관한 법률에 따른 기록 보존 기간 연결이 옳은 것은?', c:['계약 또는 청약철회 등에 관한 기록 — 5년','대금결제 및 재화 등의 공급에 관한 기록 — 1년','소비자의 불만 또는 분쟁처리에 관한 기록 — 6개월','표시·광고에 관한 기록 — 5년'], a:0, e:'대금결제·공급 5년, 불만·분쟁처리 3년, 표시·광고 6개월이다.' }
);
/* ───── 4과목 · 지문형·조합형 보강 ───── */
CPPG.mcq.push(
  { s:'s4', t:'적용기준·용어', d:3, q:'다음 〈보기〉에서 현행 「개인정보의 안전성 확보조치 기준」에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 2023년 개정으로 기술적·관리적 보호조치 기준이 폐지·통합되어 하나의 기준으로 일원화되었다\nㄴ. 종전의 유형 1·2·3 차등 적용 방식은 폐지되었다\nㄷ. 일부 조항은 처리하는 정보주체 수 등 규모 기준에 따라 적용된다\nㄹ. 정보통신서비스 제공자에게는 여전히 별도의 보호조치 기준이 적용된다\nㅁ. 기준은 기술 중립적으로 정비되었다', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ'], a:0, e:'특례 기준은 폐지·흡수되어 일반 기준으로 통합되었다.' },
  { s:'s4', t:'적용기준·용어', d:3, q:'다음 사례에서 X사에 적용되는 의무로 옳은 것은?\n\nX사는 중소기업으로 정보주체 60만명의 개인정보를 처리하며,\n그중 일부는 고유식별정보를 포함한다.\n직전 3개월간 일일평균 처리 규모는 15만명 수준이다.', c:['인터넷망 차단조치(망분리) 의무가 있다','암호키 관리절차 수립 의무가 있다','접속기록을 2년 이상 보관해야 한다','내부 관리계획 수립을 생략할 수 있다'], a:2, e:'망분리는 일일평균 100만명 이상, 중소기업의 암호키 관리절차는 100만명 이상, 내부 관리계획 생략은 1만명 미만 기준이다.' },
  { s:'s4', t:'적용기준·용어', d:3, q:'다음 〈보기〉에서 인원 규모 기준의 연결이 옳은 것을 모두 고른 것은?\n\nㄱ. 1만명 미만 — 내부 관리계획 수립 생략 가능(소상공인·개인·단체)\nㄴ. 5만명 이상 — 고유식별정보·민감정보 처리 시 접속기록 2년 보관\nㄷ. 10만명 이상 — 대기업·중견기업·공공기관의 암호키 관리절차 수립\nㄹ. 100만명 이상 — 직전 3개월 일일평균 기준의 인터넷망 차단조치\nㅁ. 1천명 이상 — 내부 관리계획 연 2회 점검', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'1천명은 유출 신고 기준이며 내부 관리계획 점검은 연 1회 이상이다.' },
  { s:'s4', t:'적용기준·용어', d:3, q:'2025년 10월 31일 시행 개정으로 변경된 내용에 해당하지 않는 것은?', c:['위험 분석 후 상응하는 보호조치를 적용하면 인터넷망 차단조치를 제외할 수 있게 되었다','접근권한 차등 부여 대상에 조회 권한이 명시되었다','접속기록 보관 대상이 개인정보처리시스템에 접속한 자로 확대되었다','유형 1·2·3에 따른 차등 적용 방식이 새로 도입되었다'], a:3, e:'유형 차등 적용은 2023년 통합 개정으로 폐지된 구 기준이다.' },
  { s:'s4', t:'적용기준·용어', d:3, q:'시행령 제30조 제1항이 정한 안전성 확보조치에 해당하지 않는 것은?', c:['개인정보에 대한 접근 권한을 제한하기 위한 조치','개인정보를 안전하게 저장·전송할 수 있는 암호화 등의 조치','개인정보 침해사고 발생에 대응하기 위한 접속기록 보관 및 위·변조 방지 조치','개인정보 수집 시 동의를 받는 방법과 절차에 관한 조치'], a:3, e:'동의 방법은 제22조·시행령 제17조의 사항이며 안전조치 항목이 아니다.' },
  { s:'s4', t:'내부관리·접근권한', d:3, q:'다음 〈보기〉에서 내부 관리계획에 포함해야 할 사항을 모두 고른 것은?\n\nㄱ. 개인정보 보호책임자의 지정과 역할·책임\nㄴ. 개인정보취급자에 대한 교육 계획\nㄷ. 접근권한·접근통제·암호화·접속기록 등 안전조치 이행 사항\nㄹ. 수탁자에 대한 관리·감독 및 위탁 계약 관련 사항\nㅁ. 임직원의 연차 사용 계획과 복리후생 기준', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'복리후생은 내부 관리계획의 사항이 아니다.' },
  { s:'s4', t:'내부관리·접근권한', d:3, q:'다음 사례에서 Y사의 조치에 대한 평가로 옳은 것은?\n\nY사는 내부 관리계획을 3년 전에 수립한 뒤\n· 조직 개편과 시스템 교체가 있었음에도 개정하지 않았고\n· 이행 실태 점검은 별도로 수행하지 않았으며\n· 취급자 교육은 신입사원 입사 시에만 실시했다', c:['내부 관리계획은 수립만으로 충분하므로 문제되지 않는다','연 1회 이상 이행 실태를 점검·개선해야 하며, 변경 사항은 반영하고 교육도 계획에 따라 시행해야 한다','점검은 3년에 1회만 하면 된다','교육은 법상 의무가 아니다'], a:1, e:'내부 관리계획은 연 1회 이상 점검·개선하고 변경 시 사유와 내용을 기록·관리해야 한다.' },
  { s:'s4', t:'내부관리·접근권한', d:3, q:'접근 권한 관리에 대한 설명으로 옳지 않은 것은?', c:['업무 수행에 필요한 최소한의 범위로 차등 부여해야 한다','인사이동이 있으면 지체 없이 권한을 변경하거나 말소해야 한다','퇴직자의 권한은 다음 정기 점검 시점까지 유지해도 무방하다','권한 부여·변경·말소 기록은 최소 3년간 보관한다'], a:2, e:'퇴직·계약 종료 시에는 즉시 권한을 회수해야 한다.' },
  { s:'s4', t:'내부관리·접근권한', d:3, q:'다음 〈보기〉에서 기록 보관 기간의 연결이 옳은 것을 모두 고른 것은?\n\nㄱ. 접근권한 부여·변경·말소 기록 — 3년\nㄴ. 접속기록 — 원칙 1년, 요건 해당 시 2년\nㄷ. 가명정보 처리 관련 기록 — 파기한 날부터 3년 이상\nㄹ. 접속기록 — 모든 처리자 일률적으로 2년\nㅁ. 접근권한 기록 — 1년', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄹ, ㅁ','ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ'], a:0, e:'접속기록 2년은 조건부이며 접근권한 기록은 3년이다.' },
  { s:'s4', t:'접근통제·인증', d:3, q:'다음 〈보기〉에서 접근통제 조치로 옳은 것을 모두 고른 것은?\n\nㄱ. 개인정보처리시스템 접속 권한을 IP 주소 등으로 제한한다\nㄴ. 외부에서 접속할 때 VPN이나 전용선 등 안전한 접속수단을 적용한다\nㄷ. 인증에 5회 이상 실패하면 추가 인증조치 등 필요한 조치를 한다\nㄹ. 1년 이상 접속하지 않은 계정은 폐쇄 등의 조치를 한다\nㅁ. 인증에 3회 실패하면 해당 계정을 영구 삭제한다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'5회 이상 실패 시 추가 인증조치이며 영구 삭제가 아니다. 1년 이상 미접속 계정은 폐쇄한다.' },
  { s:'s4', t:'접근통제·인증', d:3, q:'인터넷망 차단조치(망분리)에 대한 설명으로 옳은 것은?', c:['모든 개인정보처리자가 적용해야 하는 공통 의무다','전년도 말 기준 직전 3개월간 일일평균 100만명 이상의 개인정보를 저장·관리하는 처리자가 대상이다','정보주체 5만명 이상 처리자가 대상이다','망분리를 적용하면 접속기록 보관 의무가 면제된다'], a:1, e:'5만명은 접속기록 2년 기준이며, 망분리 적용이 다른 의무를 면제하지 않는다.' },
  { s:'s4', t:'접근통제·인증', d:3, q:'다음 사례에 대한 지적으로 옳게 묶인 것은?\n\nZ사는 개인정보처리시스템을 다음과 같이 운영한다.\n· 팀 단위 공용 계정 하나로 여러 담당자가 로그인\n· 재택근무자는 공용 인터넷으로 직접 시스템에 접속\n· 퇴사자 계정을 비활성화하지 않고 그대로 유지', c:['개인별 계정 미발급 · 안전한 접속수단 미적용 · 퇴직자 권한 미회수','공용 계정만 문제된다','재택 접속 방식만 문제된다','접근권한 관리에는 문제가 없다'], a:0, e:'계정은 개인별로 발급하고, 외부 접속에는 VPN 등 안전한 접속수단을 적용하며, 퇴직 시 즉시 권한을 회수해야 한다.' },
  { s:'s4', t:'암호화', d:3, q:'다음 〈보기〉에서 암호화에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 비밀번호는 복호화되지 않도록 일방향 암호화하여 저장한다\nㄴ. 주민등록번호는 위험도 분석 결과와 관계없이 암호화하여 저장한다\nㄷ. 정보통신망을 통해 개인정보를 송·수신할 때는 암호화한다\nㄹ. 업무용 컴퓨터나 보조저장매체에 저장할 때도 암호화가 필요하다\nㅁ. 비밀번호는 필요 시 복호화할 수 있도록 양방향 암호화한다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'비밀번호는 일방향(해시) 암호화가 원칙이다.' },
  { s:'s4', t:'암호화', d:3, q:'다음 사례에서 지적 사항으로 옳게 묶인 것은?\n\nA사의 개발팀은 다음과 같이 시스템을 구성했다.\n· 회원 비밀번호를 복호화 가능한 방식으로 저장\n· 주민등록번호는 접근권한만 제한하고 평문 저장\n· 비밀번호 해시에 MD5를 사용\n· 로그인 구간에 SSL/TLS 적용', c:['비밀번호 양방향 저장 · 주민등록번호 미암호화 · 취약 해시(MD5) 사용','비밀번호 저장 방식만 문제된다','주민등록번호 저장 방식만 문제된다','SSL/TLS 적용이 불필요하다'], a:0, e:'비밀번호는 일방향, 주민등록번호는 예외 없이 암호화하며 MD5·SHA-1은 사용 금지 대상이다.' },
  { s:'s4', t:'암호화', d:3, q:'다음 〈보기〉에서 대칭키 암호 알고리즘을 모두 고른 것은?\n\nㄱ. AES-256\nㄴ. SEED\nㄷ. RSA-2048\nㄹ. ARIA\nㅁ. ECC', c:['ㄱ, ㄴ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄷ, ㄹ, ㅁ'], a:0, e:'RSA와 ECC는 비대칭(공개키) 알고리즘이다. 국산 대칭키로는 SEED·ARIA·LEA·HIGHT가 있다.' },
  { s:'s4', t:'암호화', d:3, q:'암호 알고리즘 분류에 대한 설명으로 옳은 것은?', c:['SHA-256은 해시 알고리즘이며 권장 대상이고, MD5와 SHA-1은 사용 금지 대상이다','MD5는 권장 해시 알고리즘이다','LEA와 HIGHT는 비대칭 알고리즘이다','RSA-2048은 대칭키 알고리즘이다'], a:0, e:'LEA·HIGHT는 국산 대칭키, RSA는 비대칭이다.' },
  { s:'s4', t:'암호화', d:3, q:'암호키 관리절차 수립 의무 대상으로 옳은 것은?', c:['10만명 이상을 처리하는 대기업·중견기업·공공기관 또는 100만명 이상을 처리하는 중소기업·단체','모든 개인정보처리자','1만명 이상을 처리하는 모든 자','정보주체 5만명 이상을 처리하는 자'], a:0, e:'5만명은 접속기록 2년, 1만명 미만은 내부 관리계획 생략 기준이다.' },
  { s:'s4', t:'접속기록', d:3, q:'다음 〈보기〉에서 접속기록에 포함해야 할 항목을 모두 고른 것은?\n\nㄱ. 계정(식별자)\nㄴ. 접속일시\nㄷ. 접속지 정보\nㄹ. 수행업무\nㅁ. 정보주체의 동의 일자와 동의 범위', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'두음 계·일·지·업 — 동의 여부나 처리 목적은 접속기록 항목이 아니다.' },
  { s:'s4', t:'접속기록', d:3, q:'다음 사례에서 B사의 조치에 대한 평가로 옳은 것은?\n\nB사는 정보주체 12만명의 개인정보를 처리하며 민감정보도 함께 취급한다.\n현재 접속기록을 1년간 보관하고 6개월마다 한 번씩 점검하며,\n접속기록은 운영 서버에만 저장하고 있다.', c:['보관 기간은 2년 이상이어야 하고, 점검은 월 1회 이상이며, 위·변조 방지를 위해 별도 저장장치에 백업해야 한다','보관 기간과 점검 주기 모두 적정하다','보관 기간만 문제되고 점검 주기는 적정하다','접속기록은 운영 서버에만 저장해도 무방하다'], a:0, e:'5만명 이상이거나 민감·고유식별정보를 처리하면 2년 이상 보관하고, 월 1회 이상 점검하며 위·변조를 방지해야 한다.' },
  { s:'s4', t:'접속기록', d:3, q:'접속기록 보관 기간이 2년 이상으로 강화되는 요건에 해당하지 않는 것은?', c:['5만명 이상 정보주체의 개인정보를 처리하는 경우','고유식별정보 또는 민감정보를 처리하는 경우','기간통신사업자인 경우','내부 관리계획을 수립하지 않은 경우'], a:3, e:'2년 보관 요건은 세 가지이며 내부 관리계획 수립 여부와는 무관하다.' },
  { s:'s4', t:'접속기록', d:3, q:'접속기록 점검에 대한 설명으로 옳은 것은?', c:['월 1회 이상 점검하여 오·남용, 비정상적인 대량 다운로드 등 이상 행위를 확인한다','연 1회 점검으로 충분하다','접속기록 점검은 권고 사항이며 의무가 아니다','점검 결과 이상이 발견되어도 별도 조치 없이 기록만 남기면 된다'], a:0, e:'점검은 월 1회 이상 의무이며 이상 발견 시 사유 확인과 필요한 조치를 해야 한다.' },
  { s:'s4', t:'악성코드·물리·재해', d:3, q:'다음 〈보기〉에서 악성프로그램 방지 조치로 옳은 것을 모두 고른 것은?\n\nㄱ. 백신 등 보안 프로그램을 설치·운영한다\nㄴ. 자동 업데이트 기능을 사용하거나 매일 1회 이상 갱신·점검한다\nㄷ. 긴급 보안 업데이트 공지가 있으면 즉시 적용한다\nㄹ. 악성프로그램 발견 시 치료·격리 등 대응 조치를 한다\nㅁ. 백신 검사는 연 1회 수행하면 충분하다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'백신 검사·갱신은 매일 1회 이상이 기준이다.' },
  { s:'s4', t:'악성코드·물리·재해', d:3, q:'다음 중 점검·수행 주기의 연결이 모두 옳은 것은?', c:['내부 관리계획 점검 — 연 1회 이상 / 접속기록 점검 — 월 1회 이상 / 백신 갱신·점검 — 매일 1회 이상','내부 관리계획 점검 — 매일 / 접속기록 점검 — 연 1회 / 백신 점검 — 분기 1회','내부 관리계획 점검 — 월 1회 / 접속기록 점검 — 분기 1회 / 백신 점검 — 연 1회','내부 관리계획 점검 — 연 2회 / 접속기록 점검 — 반기 1회 / 백신 점검 — 주 1회'], a:0, e:'세 주기는 시험에서 가장 자주 뒤바뀌는 조합이다.' },
  { s:'s4', t:'악성코드·물리·재해', d:3, q:'다음 〈보기〉에서 물리적 안전조치와 재해·재난 대비에 해당하는 것을 모두 고른 것은?\n\nㄱ. 전산실·자료보관실 등의 출입통제 절차 수립·운영\nㄴ. 개인정보가 포함된 서류·보조저장매체를 잠금장치가 있는 장소에 보관\nㄷ. 보조저장매체의 반출입 통제\nㄹ. 재해·재난 시 위기대응 매뉴얼 등 대응 절차 마련과 정기 점검\nㅁ. 개인정보 수집 항목의 최소화', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'수집 최소화는 라이프사이클 단계의 원칙이지 물리적·재해 대비 조치가 아니다.' },
  { s:'s4', t:'출력·파기', d:3, q:'개인정보 출력물의 관리에 대한 설명으로 옳지 않은 것은?', c:['출력 시 용도를 특정하고 출력 항목을 최소화한다','출력·복사물의 반출입을 통제하고 관리대장 등으로 관리한다','출력물 폐기 시 파쇄하거나 소각한다','출력물은 업무 편의를 위해 사무실 공용 공간에 상시 비치한다'], a:3, e:'출력물은 노출을 최소화하고 안전한 장소에 보관·관리해야 한다.' },
  { s:'s4', t:'출력·파기', d:3, q:'다음 사례에 대한 지적으로 옳게 묶인 것은?\n\nC사는 고객 명단을 다음과 같이 관리한다.\n· 필요 항목 외에 주민등록번호까지 포함해 명단을 출력\n· 출력물을 사무실 책상 위에 상시 비치\n· 폐기 시 일반 쓰레기통에 그대로 배출', c:['출력 항목 최소화 위반 · 출력물 보관·노출 관리 미흡 · 파쇄·소각하지 않은 폐기','출력 항목 문제만 해당한다','폐기 방법만 문제된다','업무상 필요하므로 문제되지 않는다'], a:0, e:'출력 시 최소 항목 원칙, 노출 최소화, 파쇄·소각 폐기가 모두 요구된다.' },
  { s:'s4', t:'유출 대응', d:3, q:'다음 〈보기〉에서 개인정보 유출 대응 절차로 옳은 것을 모두 고른 것은?\n\nㄱ. 유출 인지 즉시 확산 방지를 위한 조치를 한다\nㄴ. 유출 항목·규모·시점·경위를 확인하고 로그와 접속기록을 확보한다\nㄷ. 정보주체에게 72시간 이내 통지하고 요건에 해당하면 72시간 이내 신고한다\nㄹ. 통지 항목을 모두 확인하지 못했더라도 확인된 사항부터 먼저 통지한다\nㅁ. 원인 분석이 끝날 때까지 통지와 신고를 보류한다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'원인 분석 완료를 기다리지 말고 기한 내에 통지·신고해야 한다.' },
  { s:'s4', t:'적용기준·용어', d:3, q:'개인정보처리자와 개인정보취급자에 대한 설명으로 옳은 것은?', c:['안전조치 의무의 이행 주체는 개인정보처리자이며, 접근권한 부여와 접속기록 관리의 대상은 개인정보취급자다','안전조치 의무의 주체는 개인정보취급자다','파견근로자는 개인정보취급자에 해당하지 않는다','공공기관은 개인정보처리자에 해당하지 않는다'], a:0, e:'주어를 바꿔 놓는 보기가 단골 오답이다.' },
  { s:'s4', t:'접근통제·인증', d:3, q:'공공시스템운영기관 특례에 대한 설명으로 옳은 것은?', c:['접근권한 부여·변경 내역을 반기 1회 이상 점검하는 등 강화된 안전조치가 적용된다','일반 개인정보처리자보다 완화된 기준이 적용된다','접속기록 보관 의무가 면제된다','민간 기업에도 동일하게 적용된다'], a:0, e:'2023년 개정의 공공기관 안전성 강화 축에 따른 특례로 2024. 9. 15. 시행되었다.' },
  { s:'s4', t:'적용기준·용어', d:2, q:'다음 중 규모와 무관하게 모든 개인정보처리자에게 적용되는 의무는?', c:['인터넷망 차단조치','암호키 관리절차 수립','파기 사유 발생 시 지체 없이 5일 이내 파기','접속기록 2년 이상 보관'], a:2, e:'파기 의무는 규모와 무관한 공통 의무이며 나머지는 규모 기준이 있다.' },
  { s:'s4', t:'암호화', d:3, q:'다음 중 저장 시 암호화 적용에 대한 설명으로 옳지 않은 것은?', c:['주민등록번호는 예외 없이 암호화하여 저장한다','비밀번호는 일방향 암호화하여 저장한다','바이오정보는 암호화하여 저장한다','여권번호는 인터넷 구간에 저장하더라도 암호화 없이 접근통제만 적용하면 된다'], a:3, e:'인터넷 구간·DMZ에 저장하는 고유식별정보는 암호화 대상이다.' }
);
/* ───── 5과목 · 지문형·조합형 보강 ───── */
CPPG.mcq.push(
  { s:'s5', t:'ISMS-P', d:3, q:'다음 〈보기〉에서 ISMS-P 인증에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 인증 영역은 3개이며 통제 항목은 101개다\nㄴ. 통제 항목은 관리체계 수립·운영 16개, 보호대책 요구사항 64개, 개인정보 처리단계별 요구사항 21개로 구성된다\nㄷ. 인증 유효기간은 3년이며 사후심사는 연 1회 이상 받는다\nㄹ. ISMS 인증의 통제 항목은 80개다\nㅁ. 인증은 KISA가 단독으로 주관한다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'주관은 KISA·개인정보보호위원회·과학기술정보통신부 3개 기관이다.' },
  { s:'s5', t:'ISMS-P', d:3, q:'다음 사례에 대한 설명으로 옳은 것은?\n\nD사는 ISMS-P 인증을 취득한 뒤 2년이 지났다.\n담당자는 "유효기간이 3년이므로 갱신심사 전까지는 별도 심사가 없다"고\n판단하고 사후 관리 활동을 축소했다.', c:['담당자의 판단이 옳다','유효기간과 무관하게 사후심사를 연 1회 이상 받아야 하므로 판단이 잘못되었다','사후심사는 인증기관이 요구할 때만 받는다','인증 취득 후에는 어떠한 심사도 없다'], a:1, e:'유효기간 3년, 사후심사는 매년(연 1회 이상), 만료 전 갱신심사를 받는다.' },
  { s:'s5', t:'ISMS-P', d:3, q:'ISMS-P 인증 절차와 심사에 대한 설명으로 옳지 않은 것은?', c:['절차는 준비·신청·계약·심사·결함 보완조치·심의의결·인증서 발급·사후관리 순으로 진행된다','결함에 대한 보완조치는 통보받은 날부터 40일 이내에 완료해야 한다','심사 종류는 최초심사·사후심사·갱신심사로 구분된다','심사 종류에는 수시심사가 포함되어 상시로 실시된다'], a:3, e:'심사 종류는 최초·사후·갱신 3가지다.' },
  { s:'s5', t:'ISMS-P', d:3, q:'ISMS와 ISMS-P의 차이에 대한 설명으로 옳은 것은?', c:['ISMS는 관리체계와 보호대책 영역으로 80개, ISMS-P는 개인정보 처리단계별 요구사항까지 포함해 101개다','ISMS가 101개, ISMS-P가 80개다','두 인증의 통제 항목 수는 동일하다','ISMS-P는 개인정보 처리단계별 요구사항만으로 구성된다'], a:0, e:'16 + 64 = 80(ISMS), 16 + 64 + 21 = 101(ISMS-P)이다.' },
  { s:'s5', t:'ISMS-P', d:3, q:'다음 〈보기〉에서 ISMS-P 인증 의무 대상 기준으로 볼 수 있는 것을 모두 고른 것은?\n\nㄱ. 정보통신망서비스를 제공하는 일정 규모 이상의 사업자\nㄴ. 개인정보를 100만명 이상 보유한 사업자\nㄷ. 전년도 매출액이 1,500억원 이상인 사업자 등 법령이 정한 기준에 해당하는 자\nㄹ. 개인정보를 1천명 이상 보유한 모든 사업자\nㅁ. 모든 공공기관', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄹ, ㅁ','ㄴ, ㄷ, ㅁ','ㄱ, ㄴ, ㄹ'], a:0, e:'1천명은 유출 신고 기준이며, 모든 공공기관의 의무 인증 대상은 아니다.' },
  { s:'s5', t:'ISMS-P', d:2, q:'ISMS-P 3개 영역 중 개인정보의 수집·이용·제공·파기 등 생명주기 단계별 요구사항을 다루는 영역은?', c:['관리체계 수립 및 운영','보호대책 요구사항','개인정보 처리단계별 요구사항','위험관리 프레임워크'], a:2, e:'처리단계별 요구사항이 21개로 구성된다.' },
  { s:'s5', t:'영향평가(PIA)', d:3, q:'다음 〈보기〉에서 개인정보 영향평가(PIA) 의무 대상에 해당하는 것을 모두 고른 것은?\n\nㄱ. 공공기관이 5만명 이상 정보주체의 민감정보 또는 고유식별정보를 처리하는 개인정보파일\nㄴ. 다른 개인정보파일과 연계한 결과 50만명 이상 정보주체의 개인정보가 포함되는 파일\nㄷ. 100만명 이상 정보주체의 개인정보파일\nㄹ. 민간 기업이 1만명 이상의 일반 개인정보를 처리하는 파일\nㅁ. 위 대상 파일을 변경하려는 경우(변경된 부분)', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ'], a:0, e:'PIA 의무는 공공기관 대상이며 5만·50만·100만 세 기준과 변경 시가 해당한다. 민간은 권장이다.' },
  { s:'s5', t:'영향평가(PIA)', d:3, q:'다음 사례에 대한 지적으로 옳게 묶인 것은?\n\nE 공공기관은 신규 민원시스템을 구축하며\n· 시스템 오픈 후 3개월이 지난 시점에 영향평가를 실시했고\n· 위험 분석에서 자산·위협·취약점만 검토했으며\n· 영향평가서를 작성했으나 개인정보위에 제출하지 않았다', c:['평가 시점 위반 · 위험 분석 요소 누락(영향) · 영향평가서 제출 누락','평가 시점만 문제된다','위험 분석 요소만 문제된다','문제될 사항이 없다'], a:0, e:'PIA는 구축 전·처리 시작 전에 수행하는 사전 평가이며, 위험 분석은 자산·위협·취약점·영향 4요소로 수행하고 결과를 제출해야 한다.' },
  { s:'s5', t:'영향평가(PIA)', d:3, q:'개인정보 영향평가 5단계의 순서로 옳은 것은?', c:['사전 준비 → 자료 수집 → 위험 분석 → 대책 수립 → 검토·이행','자료 수집 → 사전 준비 → 대책 수립 → 위험 분석 → 검토·이행','위험 분석 → 자료 수집 → 사전 준비 → 검토·이행 → 대책 수립','사전 준비 → 위험 분석 → 자료 수집 → 검토·이행 → 대책 수립'], a:0, e:'두음 사·자·위·대·검이다.' },
  { s:'s5', t:'영향평가(PIA)', d:3, q:'다음 〈보기〉에서 개인정보 영향평가에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 신규 시스템 구축 전, 개인정보 처리 시작 전에 수행하는 사전 평가다\nㄴ. 자료 수집 단계에서 개인정보 흐름표·흐름도를 작성한다\nㄷ. 평가는 개인정보위가 지정한 영향평가 기관이 수행한다\nㄹ. 2023년 개정으로 영향평가서 요약본을 공개할 수 있게 되었다\nㅁ. 위험 분석 단계에서 사후심사 결과를 반영한다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'사후심사는 ISMS-P의 절차이며 PIA 단계와 무관하다.' },
  { s:'s5', t:'수준평가·감사', d:3, q:'공공기관 개인정보 보호수준 평가에 대한 설명으로 옳은 것은?', c:['종전 관리수준 진단을 개편한 제도로, 자체평가 60점과 전문가 심층평가 40점으로 구성된다','민간 기업을 포함한 모든 개인정보처리자가 대상이다','ISMS-P 인증을 받으면 평가가 면제된다','평가 결과는 공개하지 않는다'], a:0, e:'2024년 시행으로 대상이 약 1,600여 개 기관으로 확대되었고 결과는 등급 부여·공표된다.' },
  { s:'s5', t:'수준평가·감사', d:3, q:'다음 〈보기〉에서 ISMS-P 인증과 공공기관 보호수준 평가의 비교로 옳은 것을 모두 고른 것은?\n\nㄱ. ISMS-P는 인증·심사 제도이고, 보호수준 평가는 공공기관을 대상으로 한 평가 제도다\nㄴ. 보호수준 평가의 주관은 개인정보 보호위원회다\nㄷ. ISMS-P는 KISA·개인정보위·과기정통부가 주관한다\nㄹ. 보호수준 평가 결과는 등급 부여와 공표로 이어진다\nㅁ. 두 제도는 동일한 제도로 하나만 이행하면 된다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'두 제도는 성격과 대상이 다른 별개의 제도다.' },
  { s:'s5', t:'수준평가·감사', d:3, q:'정보보호·개인정보보호 감사에 대한 설명으로 옳지 않은 것은?', c:['내부 감사, 외부 감사, 인증 감사(심사)로 구분할 수 있다','감사 표준으로는 ISACA CISA와 ISO 19011이 활용된다','감사를 받으면 내부 관리계획 연 1회 점검 등 법정 점검 의무가 면제된다','인증 감사는 인증 기준 충족 여부를 심사하는 활동이다'], a:2, e:'감사와 법정 점검 의무는 별개이며 서로 대체하지 않는다.' },
  { s:'s5', t:'국제표준·프레임워크', d:3, q:'다음 중 표준과 용도의 연결이 옳게 묶인 것은?', c:['ISO/IEC 27001 — ISMS 표준(14개 통제영역) / ISO/IEC 27701 — PIMS(27001 확장) / ISO/IEC 27018 — 클라우드 PII 처리자 보호','ISO/IEC 29100 — ISMS 인증 기준 / ISO 19011 — 클라우드 보안 표준','ISO/IEC 27018 — 프라이버시 프레임워크 / ISO/IEC 27701 — 감사 표준','ISO/IEC 29134 — ISMS 통제 기준 / ISO/IEC 27001 — 영향평가 가이드'], a:0, e:'29100은 프라이버시 프레임워크, 19011은 감사 표준, 29134는 PIA 가이드다.' },
  { s:'s5', t:'국제표준·프레임워크', d:3, q:'NIST 사이버보안 프레임워크(CSF)의 5개 기능을 옳게 나열한 것은?', c:['식별 → 보호 → 탐지 → 대응 → 복구','사전 준비 → 자료 수집 → 위험 분석 → 대책 수립 → 검토·이행','계획 → 실행 → 점검 → 개선','식별 → 평가 → 계획 → 시행 → 검토'], a:0, e:'두 번째는 PIA 5단계, 세 번째는 PDCA, 네 번째는 위험관리 5단계다.' },
  { s:'s5', t:'국제표준·프레임워크', d:3, q:'다음 〈보기〉에서 프레임워크와 단계 구성의 연결이 옳은 것을 모두 고른 것은?\n\nㄱ. NIST CSF — 식별·보호·탐지·대응·복구\nㄴ. PIA — 사전준비·자료수집·위험분석·대책수립·검토이행\nㄷ. PDCA — 계획·실행·점검·개선\nㄹ. 위험관리 — 식별·평가·계획·시행·검토\nㅁ. ISMS-P 영역 — 식별·보호·탐지', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'ISMS-P의 3개 영역은 관리체계 수립·운영, 보호대책 요구사항, 개인정보 처리단계별 요구사항이다.' },
  { s:'s5', t:'위험관리', d:3, q:'다음 사례에서 적용된 위험 처리 전략을 옳게 연결한 것은?\n\n(가) 사이버보험에 가입해 유출 사고 시 배상 비용을 충당하기로 했다\n(나) 활용도가 낮은 주민등록번호 수집 항목을 폐지했다\n(다) 잔여 위험이 목표 위험 수준 이하라고 판단해 그대로 두기로 했다\n(라) 접근통제와 암호화를 추가 도입해 위험을 낮추기로 했다', c:['(가) 전가 — (나) 회피 — (다) 수용 — (라) 감소','(가) 회피 — (나) 전가 — (다) 감소 — (라) 수용','(가) 감소 — (나) 수용 — (다) 전가 — (라) 회피','(가) 수용 — (나) 감소 — (다) 회피 — (라) 전가'], a:0, e:'보험은 전가, 활동 중단은 회피, DoA 이하 유지는 수용, 대책 적용은 감소다.' },
  { s:'s5', t:'위험관리', d:3, q:'위험 처리 전략에 대한 설명으로 옳지 않은 것은?', c:['수용은 위험이 수용 가능한 목표 수준(DoA) 이하일 때 그대로 받아들이는 것이다','감소는 보호대책을 적용해 위험 수준을 낮추는 것이다','회피는 위험을 발생시키는 활동 자체를 중단하는 것이다','전가는 보험 가입 등을 통해 법적 책임까지 제3자에게 완전히 이전하는 것이다'], a:3, e:'전가는 재무적 손실을 이전할 뿐 법적 책임은 개인정보처리자에게 남는다.' },
  { s:'s5', t:'위험관리', d:3, q:'다음 〈보기〉에서 위험관리에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 위험은 자산·위협·취약점의 관계로 파악하며 영향도를 함께 고려한다\nㄴ. DoA는 조직이 수용 가능한 목표 위험 수준을 의미한다\nㄷ. 위험 분석 방법에는 정량적 방법과 정성적 방법이 있다\nㄹ. 위험 처리 전략은 수용·감소·회피·전가로 구분한다\nㅁ. 잔여 위험은 반드시 0이 되어야 한다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'잔여 위험을 0으로 만드는 것은 현실적으로 불가능하며 DoA 이하로 관리하는 것이 목표다.' },
  { s:'s5', t:'위험관리', d:2, q:'ISMS-P 관리체계 수립·운영 영역이 따르는 관리 사이클로 옳은 것은?', c:['PDCA(계획·실행·점검·개선)','식별·보호·탐지·대응·복구','사전준비·자료수집·위험분석·대책수립·검토이행','최초·사후·갱신'], a:0, e:'관리체계 수립·운영 16개 통제는 PDCA 구조를 따른다.' },
  { s:'s5', t:'ISMS-P', d:3, q:'다음 사례에 대한 설명으로 옳은 것은?\n\nF사는 개인정보를 120만명 보유하고 있으며 ISMS-P 인증 의무 대상이다.\n담당자는 "인증을 받으면 개인정보보호법상 안전조치 의무를 이행한 것으로\n간주되므로 별도 점검은 필요 없다"고 안내했다.', c:['담당자의 안내가 옳다','인증 취득과 법상 의무 이행은 별개이므로 접속기록 점검 등 법정 의무를 계속 이행해야 한다','인증을 받으면 유출 통지 의무도 면제된다','인증을 받으면 과징금이 면제된다'], a:1, e:'인증은 관리체계 수준을 확인하는 제도일 뿐 법상 의무를 대체하지 않는다.' },
  { s:'s5', t:'수준평가·감사', d:3, q:'다음 〈보기〉에서 공공기관에만 적용되는 제도를 모두 고른 것은?\n\nㄱ. 개인정보파일의 등록 및 공개\nㄴ. 개인정보 영향평가 의무 수행\nㄷ. 개인정보 보호수준 평가\nㄹ. 개인정보 처리방침 작성·공개\nㅁ. 개인정보 유출 통지', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄹ, ㅁ','ㄴ, ㄷ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'처리방침 작성·공개와 유출 통지는 모든 개인정보처리자의 의무다.' },
  { s:'s5', t:'ISMS-P', d:3, q:'다음 중 ISMS-P 보호대책 요구사항 영역에 대한 설명으로 옳은 것은?', c:['64개 통제로 구성되며 접근통제·암호화·운영보안·침해사고 대응 등 기술·관리적 보호조치를 다룬다','16개 통제로 구성되며 PDCA 기반 거버넌스를 다룬다','21개 통제로 구성되며 개인정보 생명주기를 다룬다','101개 통제 전체를 의미한다'], a:0, e:'16은 관리체계, 21은 처리단계별, 101은 전체 합계다.' }
);

/* ══════════════════════════════════════════════════════════
   기출 유형 문항 4차 — ★사례 지문형 집중★
   실제 시험의 "상황을 주고 판단하게 하는" 형태에 맞춘 장문 문항
   ══════════════════════════════════════════════════════════ */
CPPG.mcq.push(
  /* ───── 1과목 ───── */
  { s:'s1', t:'개인정보 개념', d:3, q:'다음은 G 리서치의 데이터 처리 현황이다.\n\n· 설문 응답자의 이름을 지우고 응답번호로 대체했으며, 대응표는 별도 서버에 보관한다\n· 같은 데이터를 연령대·지역 단위로만 집계한 표도 함께 만들었다\n· 대응표를 폐기한 데이터셋도 별도로 보유하고 있다\n\n각 데이터의 법적 성격으로 옳게 묶은 것은?', c:['대응표 보관 데이터 = 가명정보 / 집계표 = 익명정보 / 대응표 폐기 데이터 = 복원 불가하면 익명정보','세 가지 모두 익명정보로 법 적용을 받지 않는다','세 가지 모두 가명정보이므로 동의 없이 마케팅에 쓸 수 있다','집계표는 가명정보, 대응표 보관 데이터는 익명정보다'], a:0, e:'경계는 추가 정보로 복원할 수 있는지에서 갈린다. 복원 가능하면 가명정보(개인정보), 불가능하면 익명정보다.' },
  { s:'s1', t:'개인정보 개념', d:3, q:'H사는 채용 과정에서 다음 정보를 수집하려 한다.\n\n· 지원자의 학력·경력\n· 지원자의 노동조합 가입 여부\n· 지원자의 주민등록번호(신원 확인 목적)\n· 면접관이 작성한 인성 평가 의견\n\n이에 대한 설명으로 옳은 것은?', c:['노동조합 가입 여부는 민감정보로 별도 동의 또는 법령 근거가 필요하고, 주민등록번호는 법령의 구체적 근거 없이 동의만으로 수집할 수 없다','노동조합 가입 여부는 일반정보이므로 자유롭게 수집할 수 있다','면접관의 평가 의견은 주관적 판단이므로 개인정보가 아니다','주민등록번호는 신원 확인 목적이면 동의로 수집할 수 있다'], a:0, e:'주관적 평가도 개인정보이며, 주민등록번호는 동의로 처리할 수 없다.' },
  { s:'s1', t:'프라이버시·특성', d:3, q:'다음 대화에서 잘못된 설명을 한 사람은?\n\n· 甲: 프라이버시권은 사생활을 침해받지 않을 소극적 권리에 가깝습니다\n· 乙: 개인정보 자기결정권은 자신의 정보를 통제하는 적극적 권리입니다\n· 丙: 개인정보 자기결정권은 헌법에 명문 조항으로 직접 규정되어 있습니다\n· 丁: 국내법에서는 법 제4조가 정보주체의 권리로 이를 구체화하고 있습니다', c:['甲','乙','丙','丁'], a:2, e:'자기결정권은 헌법 제10조·제17조에서 도출된 기본권으로 헌법재판소가 인정한 것이며 명문 조항으로 직접 규정된 것은 아니다.' },
  { s:'s1', t:'국제 규범·GDPR', d:3, q:'다음 〈보기〉에서 GDPR과 국내 개인정보보호법의 비교로 옳은 것을 모두 고른 것은?\n\nㄱ. GDPR의 원칙은 7개, 국내법 제3조의 보호원칙은 8개다\nㄴ. GDPR에는 책임성 원칙이 있고, 국내법에는 익명·가명 처리 노력이 있다\nㄷ. GDPR의 과징금 상한은 전 세계 매출 4%, 국내법은 전체 매출액의 3%다\nㄹ. GDPR의 DPO와 국내법의 CPO는 같은 법령에 근거한 동일 제도다\nㅁ. 국내법은 공공·민간을 함께 규율하는 통합법이다', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ'], a:0, e:'DPO는 GDPR, CPO는 국내법 용어로 근거 법령이 다르다.' },
  { s:'s1', t:'국제 규범·GDPR', d:3, q:'다음은 I사의 해외 진출 검토 내용이다.\n\n· EU 이용자 대상 서비스를 준비 중이며 EU 내 사업장은 없다\n· 이용자 데이터는 국내 데이터센터에 저장한다\n· 자동화된 신용평가로 서비스 등급을 결정할 계획이다\n\n검토 결과로 가장 적절한 것은?', c:['GDPR이 역외 적용될 수 있으므로 적법 근거·정보주체 권리·유출 통지 절차를 GDPR 기준으로 준비해야 한다','국내 서버를 사용하므로 GDPR은 적용되지 않는다','EU 사업장이 없으면 GDPR 적용 대상이 아니다','자동화 결정은 GDPR에서 규율하지 않는다'], a:0, e:'GDPR은 역외 적용되며 자동화된 결정에 관한 권리도 규정하고 있다.' },
  { s:'s1', t:'조직·국제표준', d:3, q:'J사는 개인정보 보호 조직을 다음과 같이 운영한다.\n\n· CPO를 지정하지 않았고 대표이사도 자신이 CPO라고 인식하지 않는다\n· 개인정보 보호 업무는 IT 운영팀장이 겸임하되 인사평가는 IT 본부장이 한다\n· CPO가 발견한 위반 사항은 분기 보고서로만 정리한다\n\n이에 대한 지적으로 옳게 묶인 것은?', c:['미지정 시 사업주·대표자가 CPO가 된다는 점 · 독립성과 불이익 금지 보장 필요 · 위반 사실 인지 시 즉시 개선조치 필요','CPO를 지정하지 않았으므로 법상 아무런 책임이 없다','겸임 자체가 금지되므로 그 점만 위반이다','분기 보고는 적절한 조치이므로 문제되지 않는다'], a:0, e:'CPO는 위반 사실을 알게 되면 즉시 개선조치하고 필요 시 대표자에게 보고해야 한다.' },
  { s:'s1', t:'개인정보 개념', d:3, q:'다음 〈보기〉에서 개인정보에 해당하지 않는 것을 모두 고른 것은?\n\nㄱ. 사망한 사람의 병력 정보(유족과 무관하게 활용)\nㄴ. 법인의 대표전화번호와 사업자등록번호\nㄷ. 복원이 불가능하도록 처리된 통계 집계값\nㄹ. 다른 정보와 쉽게 결합하여 개인을 알아볼 수 있는 접속 로그\nㅁ. 추가 정보를 사용하면 복원할 수 있는 가명처리된 회원 정보', c:['ㄱ, ㄴ, ㄷ','ㄱ, ㄹ, ㅁ','ㄴ, ㄷ, ㅁ','ㄷ, ㄹ, ㅁ'], a:0, e:'결합으로 식별 가능한 로그와 가명정보는 개인정보에 해당한다.' },
  { s:'s1', t:'조직·국제표준', d:2, q:'다음 중 개인정보 보호와 정보보호 관련 표준의 성격이 다른 하나는?', c:['ISO/IEC 27001','ISO/IEC 27701','ISO/IEC 27018','ISO 19011'], a:3, e:'앞의 세 가지는 관리체계·통제 기준이고 ISO 19011은 감사 수행 지침이다.' },

  /* ───── 2과목 ───── */
  { s:'s2', t:'동의 제도', d:3, q:'K 병원은 진료 예약 시스템을 개편하며 다음과 같이 동의를 설계했다.\n\n· 진료 목적 개인정보 수집·이용 동의(필수)\n· 건강검진 결과 등 건강정보 처리 동의를 위 항목에 포함해 함께 받음\n· 병원 홍보 문자 발송 동의(필수)\n· 동의 화면의 보유기간 문구는 작은 회색 글씨로 표시\n\n위반 사항으로 옳게 묶인 것은?', c:['민감정보 별도 동의 미분리 · 홍보 동의를 필수로 설정 · 중요 내용 명확 표시 위반','민감정보 별도 동의 미분리만 위반이다','홍보 동의 설정만 위반이다','위반 사항이 없다'], a:0, e:'건강정보는 민감정보로 별도 동의가 필요하고, 홍보는 선택 동의이며 중요 내용은 9포인트 이상으로 구분 표시해야 한다.' },
  { s:'s2', t:'동의 제도', d:3, q:'다음 상황에서 정보주체의 동의가 필요한 처리를 모두 고른 것은?\n\nㄱ. 통신사가 요금 청구를 위해 이용 내역을 처리하는 경우\nㄴ. 쇼핑몰이 제휴사 상품 광고 문자를 보내기 위해 연락처를 이용하는 경우\nㄷ. 병원이 감염병 예방법에 따라 역학조사 자료를 제출하는 경우\nㄹ. 보험사가 가입자의 건강정보를 심사에 활용하는 경우\nㅁ. 응급실이 의식불명 환자의 보호자 연락처를 확인하는 경우', c:['ㄴ, ㄹ','ㄱ, ㄷ','ㄷ, ㅁ','ㄱ, ㄹ, ㅁ'], a:0, e:'계약 이행·법령 근거·급박한 생명의 이익은 동의가 필요 없고, 홍보와 민감정보 처리는 별도 동의가 필요하다.' },
  { s:'s2', t:'유출 통지·신고', d:3, q:'L사는 다음과 같은 유출 사고를 인지했다.\n\n· 협력사 직원이 권한 없이 회원 명단을 내려받아 외부로 전달\n· 유출 인원은 350명이며 이름·연락처가 포함되었다\n· 주민등록번호나 민감정보는 포함되지 않았다\n· 유출 경로가 확인되어 자료를 전량 회수·삭제했고 추가 확산은 확인되지 않았다\n\n이에 대한 설명으로 가장 적절한 것은?', c:['정보주체에게는 72시간 이내 통지해야 하며, 유출 경로 확인과 회수로 권익 침해 가능성이 현저히 낮아졌다면 신고는 하지 않을 수 있다','1천명 미만이므로 통지도 신고도 필요 없다','인원과 무관하게 항상 신고해야 한다','회수했으므로 통지 의무도 사라진다'], a:0, e:'통지에는 인원 기준이 없고, 신고 생략 요건은 유출 경로 확인과 회수·삭제 등으로 권익 침해 가능성이 현저히 낮아진 경우다.' },
  { s:'s2', t:'유출 통지·신고', d:3, q:'다음 중 개인정보 유출로 볼 수 있는 사례를 모두 고른 것은?\n\nㄱ. 개인정보가 저장된 USB를 분실한 경우\nㄴ. 권한 없는 자가 개인정보처리시스템에 접근한 경우\nㄷ. 담당자의 실수로 다른 고객에게 회원 명단이 발송된 경우\nㄹ. 내부 직원이 정당한 권한으로 업무상 개인정보를 조회한 경우\nㅁ. 홈페이지 오류로 다른 사람의 주문 내역이 노출된 경우', c:['ㄱ, ㄴ, ㄷ, ㅁ','ㄱ, ㄷ, ㄹ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㄹ'], a:0, e:'정당한 권한에 의한 업무상 조회는 유출이 아니다.' },
  { s:'s2', t:'정보주체 권리·구제', d:3, q:'M사는 고객 甲으로부터 다음 요구를 받았다.\n\n· 본인의 상담 이력 열람과 사본 발급\n· 잘못 기재된 주소의 정정\n· 마케팅 목적 처리의 정지와 동의 철회\n\nM사의 대응으로 옳지 않은 것은?', c:['열람 요구에 대해 법정 제한 사유가 없으면 사본 발급을 포함해 열람하게 한다','정정 요구에 대해 필요한 조사를 하고 지체 없이 정정한 뒤 결과를 알린다','처리정지 요구는 계약 이행이 곤란하다는 이유만 들면 언제든 거절할 수 있다','동의 철회 시 해당 개인정보를 지체 없이 복구·재생할 수 없도록 파기한다'], a:2, e:'계약 이행 곤란을 이유로 한 거절은 정보주체가 계약 해지 의사를 명확히 밝히지 않은 경우에 한한다.' },
  { s:'s2', t:'정보주체 권리·구제', d:3, q:'다음 사례에 대한 설명으로 옳은 것은?\n\nN사는 AI 모델로 대출 한도를 자동 산정해 통보하며,\n산정 기준과 절차는 영업비밀이라는 이유로 일절 공개하지 않는다.\n고객 乙은 결과에 이의를 제기하며 설명을 요구했다.', c:['자동화된 결정이 권리·의무에 중대한 영향을 미치면 정보주체는 거부하거나 설명을 요구할 수 있고, 처리자는 기준·절차 등을 공개해야 한다','자동화된 결정에 대한 설명 요구권은 국내법에 없다','영업비밀이면 어떠한 정보도 공개할 필요가 없다','자동화된 결정은 언제나 거부할 수 있다'], a:0, e:'2023년 개정으로 신설된 권리이며, 동의·법률·계약에 근거한 결정에는 거부권이 제한될 수 있다.' },
  { s:'s2', t:'분쟁조정·단체소송', d:3, q:'다음 사건 진행 순서에 대한 설명으로 옳은 것은?\n\n· 동일한 유출 사고 피해자 80명이 집단분쟁조정을 신청했다\n· 개인정보처리자가 조정안을 수락하지 않았다\n· 소비자단체가 침해행위 중지를 구하는 소를 제기하려 한다', c:['집단분쟁조정 거부·불수락이 있었으므로 단체소송 요건을 갖출 수 있고, 청구 범위는 금지·중지 청구로 한정된다','집단분쟁조정 없이도 단체소송을 제기할 수 있었다','단체소송에서 손해배상까지 함께 청구할 수 있다','집단분쟁조정은 100명 이상이어야 신청할 수 있다'], a:0, e:'집단분쟁조정은 50명 이상이 요건이며, 단체소송은 조정 거부·불수락이 전제다.' },
  { s:'s2', t:'분쟁조정·단체소송', d:3, q:'개인정보 분쟁조정 진행 중 다음 상황이 발생했다.\n\n· 신청인이 조정 절차 진행 중 법원에 소를 제기했다\n\n이에 대한 처리로 옳은 것은?', c:['분쟁조정위원회는 조정 절차를 중지하고 당사자에게 알린다','조정 절차를 계속 진행하여 조정안을 제시한다','소송과 조정을 병행하여 모두 진행한다','조정 신청이 자동으로 인용된다'], a:0, e:'처리 중 한쪽 당사자가 소를 제기하면 조정을 중지하고 통지한다.' },
  { s:'s2', t:'감독기구·제재', d:3, q:'다음 사례에서 적용될 수 있는 제재를 옳게 묶은 것은?\n\nO사는 안전조치를 소홀히 하여 회원 50만명의 개인정보를 유출했고,\n조사 과정에서 고의에 가까운 관리 부실이 확인되었다.\n피해자 일부는 정신적 피해를 주장하나 손해액 입증이 어렵다.', c:['전체 매출액 3% 이하 과징금 · 징벌적 손해배상(5배 이내) · 법정 손해배상(300만원 이하)','과태료 3천만원만 부과된다','손해배상은 실손해액 범위로만 가능하다','공공기관이 아니므로 과징금 대상이 아니다'], a:0, e:'과징금·형벌·손해배상은 병존할 수 있으며 법정 손해배상은 입증 부담을 덜어준다.' },
  { s:'s2', t:'CCTV·처리방침', d:3, q:'P 아파트 관리사무소의 CCTV 운영에 대한 설명으로 옳은 것은?\n\n· 지하주차장과 놀이터에 CCTV를 설치했다\n· 입주민 요청으로 특정 세대 현관을 확대 촬영했다\n· 안내판에는 설치 목적과 관리책임자 연락처를 적었으나 촬영 범위와 시간은 적지 않았다', c:['특정 세대를 확대 촬영한 것은 임의 조작·목적 외 촬영에 해당하고, 안내판에는 촬영 범위와 시간도 적어야 한다','입주민 요청이 있었으므로 확대 촬영은 적법하다','안내판에는 관리책임자 연락처만 적으면 된다','주차장과 놀이터 설치는 허용 사유가 없어 위법하다'], a:0, e:'시설안전·범죄예방 목적의 설치는 가능하나 임의 조작·다른 곳 촬영은 금지되며 안내판에는 4항목을 적어야 한다.' },
  { s:'s2', t:'CCTV·처리방침', d:3, q:'다음 〈보기〉에서 개인정보 처리방침 운영에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 처리방침은 정보주체가 쉽게 확인할 수 있도록 인터넷 홈페이지에 지속적으로 게재한다\nㄴ. 처리방침을 변경하면 변경 사유와 내용을 지체 없이 공개한다\nㄷ. 처리방침의 내용과 계약 내용이 다르면 정보주체에게 유리한 것을 적용한다\nㄹ. 홈페이지가 없으면 사업장 게시, 관보·신문 게재 등의 방법을 사용할 수 있다\nㅁ. 처리방침은 약관에 해당하므로 약관 심사를 받아야 한다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'처리방침은 약관으로 보기 어렵다.' },
  { s:'s2', t:'조직·책임자', d:3, q:'다음 중 개인정보 보호책임자와 국내대리인 제도를 옳게 비교한 것은?', c:['CPO는 개인정보처리자가 지정하는 내부 책임자이고, 국내대리인은 국내에 주소·영업소가 없는 처리자가 지정한다','CPO와 국내대리인은 동일한 제도의 다른 명칭이다','국내대리인은 모든 국내 사업자가 지정해야 한다','CPO는 해외 사업자만 지정한다'], a:0, e:'국내대리인의 성명·주소·연락처는 처리방침에 공개한다.' },
  { s:'s2', t:'법체계·원칙', d:3, q:'다음 사례에 대한 법 적용 설명으로 옳은 것은?\n\n금융회사 Q사는 신용정보법에 따라 신용정보 수집 동의를 받고 있으며,\n홈페이지에 개인정보 처리방침을 게시하는 문제로 검토 중이다.', c:['신용정보법에 특별한 규정이 있는 사항은 신용정보법이 우선하고, 규정이 없는 처리방침 게시 등은 개인정보보호법이 적용된다','금융회사에는 개인정보보호법이 전혀 적용되지 않는다','개인정보보호법이 항상 우선하므로 신용정보법은 적용되지 않는다','두 법 중 회사가 유리한 것을 선택해 적용할 수 있다'], a:0, e:'개인정보보호법은 일반법으로 특별법이 규정하지 않은 사항에 보충 적용된다.' },
  { s:'s2', t:'개정 연혁', d:3, q:'다음 〈보기〉에서 2023년 전면개정의 축과 항목 연결이 옳은 것을 모두 고른 것은?\n\nㄱ. 정보주체 권익 보호 — 분쟁조정 의무 참여 대상 확대\nㄴ. 온·오프라인 이중규제 개선 — 정보통신서비스 제공자 특례 삭제\nㄷ. 공공기관 안전성 강화 — 개인정보파일 등록 확대\nㄹ. 글로벌 스탠다드 — 과징금 전체 매출액 기준 개편\nㅁ. 정보주체 권익 보호 — 인터넷망 차단조치 신설', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'망 차단조치는 안전성 확보조치 기준(고시)의 사항이며 전면개정 4축의 항목이 아니다.' },
  { s:'s2', t:'정보주체 권리·구제', d:3, q:'다음 중 손해배상책임 보장제도(보험·공제 가입 등)에 대한 설명으로 옳은 것은?', c:['시행령이 정한 기준에 해당하는 사업자는 보험·공제 가입이나 준비금 적립을 해야 하며 미이행 시 과태료 대상이다','모든 개인정보처리자가 반드시 보험에 가입해야 한다','보험에 가입하면 유출 사고의 법적 책임이 면제된다','징벌적 손해배상과 동일한 제도다'], a:0, e:'미이행 시 2천만원 이하 과태료가 부과될 수 있으며 책임이 면제되지는 않는다.' },
  { s:'s2', t:'감독기구·제재', d:3, q:'다음 〈보기〉에서 형사처벌 대상이 될 수 있는 행위를 모두 고른 것은?\n\nㄱ. 거짓이나 그 밖의 부정한 수단으로 개인정보를 취득한 행위\nㄴ. 가명정보를 특정 개인을 알아보기 위한 목적으로 처리한 행위\nㄷ. 개인정보 처리방침을 공개하지 않은 행위\nㄹ. 업무상 알게 된 개인정보를 누설하거나 권한 없이 타인에게 제공한 행위\nㅁ. 개인정보 보호책임자를 지정하지 않은 행위', c:['ㄱ, ㄴ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄷ, ㄹ','ㄱ, ㄹ, ㅁ'], a:0, e:'처리방침 미공개와 CPO 미지정은 과태료 대상이다.' },

  /* ───── 3과목 ───── */
  { s:'s3', t:'제공·위탁', d:3, q:'다음은 R 은행의 업무 처리 현황이다.\n\n(가) 카드 발급 인쇄·배송 업무를 전문업체에 맡김\n(나) 계열 보험사에 고객 정보를 제공해 보험 상품을 권유하게 함\n(다) 채권 추심 업무를 추심 전문회사에 맡김\n(라) 마케팅 문자 발송 업무를 대행사에 맡김\n\n각 경우에 필요한 조치로 옳은 것은?', c:['(가)(다)(라)는 위탁으로 공개가 필요하고, 그중 (라)는 정보주체 통지까지 필요하며, (나)는 제3자 제공으로 별도 동의가 필요하다','네 경우 모두 별도 동의가 필요하다','네 경우 모두 위탁이므로 공개만 하면 된다','(나)만 위탁이고 나머지는 제3자 제공이다'], a:0, e:'홍보·판매 권유 업무 위탁은 공개에 더해 정보주체에게 알려야 한다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'다음 사례에서 책임 관계에 대한 설명으로 옳은 것은?\n\nS사는 고객 데이터 처리 업무를 T사에 위탁했고,\nT사 직원의 부주의로 데이터가 유출되어 정보주체에게 손해가 발생했다.', c:['수탁자를 위탁자의 소속 직원으로 보아 위탁자가 손해배상 책임을 지며, 수탁자도 법의 주요 조문 적용을 받아 제재 대상이 될 수 있다','수탁자만 책임을 지고 위탁자는 책임이 없다','위탁자만 책임을 지고 수탁자는 어떠한 제재도 받지 않는다','정보주체는 위탁자와 수탁자 어느 쪽에도 배상을 청구할 수 없다'], a:0, e:'2023년 개정으로 수탁자에게도 주요 조문이 준용되어 과징금·과태료·형벌 대상이 된다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'다음 〈보기〉에서 위탁 시 반드시 이행해야 하는 사항을 모두 고른 것은?\n\nㄱ. 위탁 계약을 문서로 체결한다\nㄴ. 위탁하는 업무의 내용과 수탁자를 홈페이지 등에 공개한다\nㄷ. 수탁자에게 교육을 실시하고 처리 현황을 점검·감독한다\nㄹ. 수탁자가 재위탁하려면 위탁자의 동의를 받도록 한다\nㅁ. 위탁 시마다 정보주체 전원의 서면 동의를 받는다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'위탁은 동의가 아니라 공개(홍보·판매권유는 통지)로 처리한다.' },
  { s:'s3', t:'수집·이용', d:3, q:'다음 사례에 대한 지적으로 옳은 것은?\n\nU 학원은 수강 신청서에서\n· 학생의 이름·연락처·학교와 함께 학부모 직업·연소득을 필수로 받고\n· 수집 목적을 "학원 운영 전반"으로만 기재했으며\n· 보유기간은 "회원 탈퇴 시까지"로만 적었다', c:['서비스 제공에 불필요한 항목의 필수 수집, 목적의 구체성 부족, 보유기간 고지의 불명확성이 문제된다','필수 항목 지정은 사업자의 재량이므로 문제되지 않는다','목적을 포괄적으로 적는 것이 오히려 바람직하다','보유기간은 고지 사항이 아니다'], a:0, e:'최소 수집 원칙과 고지 4사항(목적·항목·기간·거부권)을 구체적으로 지켜야 한다.' },
  { s:'s3', t:'수집·이용', d:3, q:'다음 중 목적 외 이용·제공에 해당하여 별도의 법적 근거가 필요한 사례는?', c:['배송을 위해 수집한 주소를 이용해 다른 계열사 상품 카탈로그를 발송하는 경우','요금 청구를 위해 수집한 정보를 청구서 발송에 이용하는 경우','회원 가입 시 수집한 이메일로 서비스 점검 공지를 보내는 경우','예약 확인을 위해 수집한 연락처로 예약 변경을 안내하는 경우'], a:0, e:'수집 목적과 다른 마케팅 활용은 목적 외 이용에 해당한다.' },
  { s:'s3', t:'보유·파기', d:3, q:'다음 사례에 대한 설명으로 옳은 것은?\n\nV 쇼핑몰은 회원 탈퇴 시\n· 회원정보를 즉시 삭제하되\n· 전자상거래법상 보존 의무가 있는 계약·결제 기록은 별도 테이블로 옮겨 접근권한을 최소화하고\n· 처리방침에 보존 근거와 항목을 적어 두었다', c:['법령상 보존 의무가 있는 정보를 분리 보관하고 근거를 공개한 것으로 적절한 처리다','보존 의무가 있어도 탈퇴 시 모두 삭제해야 하므로 위법이다','분리 보관 사실은 공개할 필요가 없다','보존 기록은 마케팅에 활용해도 무방하다'], a:0, e:'분리 저장·관리와 처리방침 기재가 요구되며 보존 목적 외 이용은 허용되지 않는다.' },
  { s:'s3', t:'보유·파기', d:3, q:'다음 〈보기〉에서 파기 실무로 적절한 것을 모두 고른 것은?\n\nㄱ. 운영 데이터베이스뿐 아니라 백업본과 로그에 남은 사본도 함께 파기한다\nㄴ. 파기 대상·시점·방법·담당자를 기록으로 남긴다\nㄷ. 전자적 파일은 복원할 수 없는 방법으로 삭제한다\nㄹ. 개발·테스트 환경에 복제된 실데이터도 파기 대상에 포함한다\nㅁ. 파기 여부는 담당자 판단에 맡기고 별도 승인 절차는 두지 않는다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'파기는 절차와 승인·기록을 갖추어 수행해야 한다.' },
  { s:'s3', t:'광고성 정보', d:3, q:'다음 사례에서 적법한 처리로 볼 수 있는 것은?', c:['수신동의를 받은 회원에게 오전 10시에 (광고) 표기와 수신거부 방법을 포함해 문자를 보냈다','수신거부한 회원에게 2년이 지난 뒤 재발송했다','수신동의 여부를 확인하지 않고 22시에 문자를 보냈다','(광고) 표기 없이 이벤트 안내 문자를 보냈다'], a:0, e:'야간(21~08시) 전송은 별도 동의가 필요하고, 수신거부자에게는 기간 제한 없이 전송할 수 없다.' },
  { s:'s3', t:'국외이전·양도', d:3, q:'다음 사례에서 W사가 취해야 할 조치로 가장 적절한 것은?\n\nW사는 해외 본사와 고객 데이터를 공유하려 하며,\n계약 이행에 필요한 범위를 넘어 마케팅 분석에도 활용할 계획이다.', c:['국외 이전에 관한 별도 동의를 받고 이전받는 자·국가·목적·보유기간·거부 절차 등을 알려야 한다','계약 이행 목적이면 어떤 활용도 동의 없이 가능하다','국외 이전은 신고만 하면 된다','해외 본사 간 이전은 국외 이전에 해당하지 않는다'], a:0, e:'계약 이행에 필요한 범위를 넘는 활용은 별도 동의 등 적법 근거가 필요하다.' },
  { s:'s3', t:'국외이전·양도', d:3, q:'다음 〈보기〉에서 영업양도에 따른 개인정보 이전 시 옳은 처리를 모두 고른 것은?\n\nㄱ. 이전 사실과 양수자의 연락처, 이전을 원하지 않을 때의 조치 방법을 알린다\nㄴ. 양수자는 이전 당시의 본래 목적 범위에서만 이용·제공한다\nㄷ. 정보주체가 이전을 원하지 않으면 그 의사에 따른 조치를 할 수 있어야 한다\nㄹ. 양수자는 개인정보처리자로서 법상 의무를 부담한다\nㅁ. 양수자는 이전받은 정보를 새로운 마케팅 목적으로 자유롭게 활용할 수 있다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'목적 변경에는 별도의 적법 근거가 필요하다.' },
  { s:'s3', t:'가명정보', d:3, q:'다음 사례에 대한 설명으로 옳은 것은?\n\nX 연구팀은 병원 진료데이터와 공공기관 통계데이터를 결합해\n질병 예측 연구를 하려 한다. 두 데이터는 서로 다른 기관이 보유하고 있다.', c:['가명처리 후 지정된 결합전문기관을 통해 결합해야 하며 반출은 가명 또는 익명 처리 후 승인을 받아야 한다','연구 목적이면 두 기관이 직접 결합할 수 있다','결합 후에는 재식별 금지 의무가 적용되지 않는다','결합 데이터는 익명정보이므로 안전조치가 필요 없다'], a:0, e:'임의 결합은 금지되며 결합 이후에도 안전조치와 재식별 금지가 적용된다.' },
  { s:'s3', t:'처리 제한', d:3, q:'다음 사례에서 적법 여부 판단으로 옳은 것은?\n\nY 헬스장은 회원 관리를 위해\n· 지문 인식으로 출입을 확인하고\n· 건강 상담을 위해 질병 이력을 기록하며\n· 회원 확인용으로 주민등록번호를 수집한다', c:['지문 등 생체인식정보와 질병 이력은 민감정보로 별도 동의 또는 법령 근거가 필요하고, 주민등록번호는 법령 근거 없이 수집할 수 없다','세 가지 모두 일반 개인정보이므로 동의 하나로 처리할 수 있다','생체인식정보는 고유식별정보이므로 동의로 처리할 수 있다','주민등록번호는 회원 확인 목적이면 수집할 수 있다'], a:0, e:'생체인식정보와 건강정보는 민감정보이며 주민등록번호는 법령의 구체적 근거가 필요하다.' },
  { s:'s3', t:'영상정보', d:3, q:'다음 중 이동형 영상정보처리기기 운영으로 적법한 것은?', c:['배달 로봇에 부착한 카메라로 촬영하며 불빛과 소리로 촬영 사실을 알리고, 업무 목적 촬영에 필요한 근거를 갖춘 경우','업무 목적이라는 이유만으로 아무 표시 없이 촬영하는 경우','드론으로 사생활 침해 우려가 있는 장소를 촬영하는 경우','촬영과 함께 음성을 녹음하는 경우'], a:0, e:'이동형 기기는 촬영 사실을 표시해야 하며 업무 목적 촬영에는 별도의 근거가 필요하다.' },
  { s:'s3', t:'수집·이용', d:3, q:'다음 〈보기〉에서 개인정보 수집 시 정보주체에게 알려야 할 사항을 모두 고른 것은?\n\nㄱ. 개인정보의 수집·이용 목적\nㄴ. 수집하려는 개인정보의 항목\nㄷ. 개인정보의 보유 및 이용 기간\nㄹ. 동의를 거부할 권리가 있다는 사실과 거부에 따른 불이익\nㅁ. 개인정보처리자의 연간 매출액과 임직원 수', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'두음 수·항·기·거다.' },
  { s:'s3', t:'제공·위탁', d:3, q:'다음 중 개인정보 제3자 제공과 처리위탁을 판단하는 기준으로 가장 적절한 것은?', c:['개인정보를 누구의 목적과 이익을 위해 처리하는지, 처리 과정에 대한 관리·감독이 누구에게 있는지','개인정보를 전달하는 방법이 온라인인지 오프라인인지','전달되는 개인정보의 양이 많은지 적은지','계약 금액이 큰지 작은지'], a:0, e:'목적 귀속과 관리·감독 범위가 핵심 판단 기준이다.' },
  { s:'s3', t:'보유·파기', d:2, q:'다음 중 개인정보 보유기간 관리로 적절하지 않은 것은?', c:['수집 항목별로 보유 근거와 기간을 관리대장으로 유지한다','보유기간이 지난 정보는 파기 사유가 발생한 것으로 보고 지체 없이 파기한다','보유기간을 정하지 않고 서비스 종료 시점까지 무기한 보관한다','법령상 보존 의무가 있는 정보는 분리 보관한다'], a:2, e:'보유기간은 동의받은 기간 또는 법령이 정한 기간으로 한정해야 한다.' },

  /* ───── 4과목 ───── */
  { s:'s4', t:'적용기준·용어', d:3, q:'다음 세 기업의 의무를 옳게 판단한 것은?\n\n· A사(대기업): 정보주체 30만명 처리, 고유식별정보 포함\n· B사(소상공인): 정보주체 8천명 처리\n· C사(중소기업): 정보주체 150만명 처리, 직전 3개월 일일평균 120만명', c:['A사는 암호키 관리절차와 접속기록 2년 보관, B사는 내부 관리계획 생략 가능, C사는 망 차단조치와 암호키 관리절차 대상','A사는 망 차단조치 대상, B사는 접속기록 2년 대상, C사는 의무 없음','세 기업 모두 망 차단조치 대상이다','세 기업 모두 내부 관리계획을 생략할 수 있다'], a:0, e:'10만명 이상 대기업은 암호키 관리절차, 1만명 미만 소상공인은 내부 관리계획 생략, 일일평균 100만명 이상은 망 차단 대상이다.' },
  { s:'s4', t:'접속기록', d:3, q:'다음 사례에서 확인해야 할 접속기록 항목으로 옳은 것은?\n\n개인정보 유출이 의심되어 내부 조사를 시작했다.\n어떤 계정이 언제 어디에서 접속해 무엇을 했는지 확인하려 한다.', c:['계정(식별자) · 접속일시 · 접속지 정보 · 수행업무','정보주체의 동의 일자 · 처리 목적 · 보유기간 · 파기 예정일','계정 · 처리 목적 · 동의 여부 · 수행업무','접속일시 · 보유기간 · 동의 범위 · 파기 방법'], a:0, e:'두음 계·일·지·업이며 동의·목적·보유기간은 접속기록 항목이 아니다.' },
  { s:'s4', t:'접속기록', d:3, q:'다음 〈보기〉에서 접속기록 관리에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 원칙적으로 1년 이상 보관한다\nㄴ. 5만명 이상 처리, 고유식별·민감정보 처리, 기간통신사업자 중 하나에 해당하면 2년 이상 보관한다\nㄷ. 월 1회 이상 점검하여 오·남용을 확인한다\nㄹ. 위·변조를 막기 위해 별도의 저장장치에 백업한다\nㅁ. 점검 결과 이상이 발견되어도 별도 조치는 필요 없다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'이상 발견 시 사유 확인과 필요한 조치를 해야 한다.' },
  { s:'s4', t:'암호화', d:3, q:'다음은 D사의 암호화 적용 현황이다.\n\n· 비밀번호: SHA-256 해시로 저장\n· 주민등록번호: AES-256으로 암호화 저장\n· 여권번호: 인터넷 구간 서버에 평문 저장\n· 로그인·결제 구간: TLS 적용\n\n지적할 사항으로 옳은 것은?', c:['인터넷 구간에 저장하는 여권번호를 암호화하지 않은 점','비밀번호를 일방향으로 저장한 점','주민등록번호를 암호화한 점','전송 구간에 TLS를 적용한 점'], a:0, e:'인터넷 구간·DMZ에 저장하는 고유식별정보는 암호화 대상이다.' },
  { s:'s4', t:'암호화', d:3, q:'다음 〈보기〉에서 암호 알고리즘 분류가 옳은 것을 모두 고른 것은?\n\nㄱ. AES-256 — 대칭키\nㄴ. SEED·ARIA·LEA·HIGHT — 국산 대칭키\nㄷ. RSA-2048 — 비대칭키\nㄹ. SHA-256 — 해시\nㅁ. MD5 — 권장 해시', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'MD5와 SHA-1은 사용 금지 대상이다.' },
  { s:'s4', t:'내부관리·접근권한', d:3, q:'다음 사례에서 접근권한 관리의 문제점으로 옳게 묶인 것은?\n\nE사는 다음과 같이 권한을 운영한다.\n· 신입사원에게 선임과 동일한 전체 조회 권한을 부여\n· 부서 이동 후에도 이전 부서 권한을 유지\n· 권한 변경 이력은 6개월만 보관', c:['최소권한 원칙 위반 · 인사이동 시 권한 미조정 · 권한 기록 3년 보관 위반','최소권한 원칙 위반만 해당한다','권한 기록 보관 기간만 문제된다','문제될 사항이 없다'], a:0, e:'권한은 업무에 필요한 최소 범위로 차등 부여하고 인사이동 시 지체 없이 조정하며 기록은 3년 보관한다.' },
  { s:'s4', t:'접근통제·인증', d:3, q:'다음 중 접근통제 조치로 적절하지 않은 것은?', c:['개인정보처리시스템 접속을 허용된 IP 대역으로 제한','외부 접속 시 VPN 등 안전한 접속수단 적용','업무 편의를 위해 부서 공용 계정을 발급하고 비밀번호를 공유','1년 이상 접속하지 않은 계정을 폐쇄'], a:2, e:'계정은 개인별로 발급해야 하며 공용 계정과 비밀번호 공유는 접근통제 위반이다.' },
  { s:'s4', t:'유출 대응', d:3, q:'다음 상황에서 F사가 가장 먼저 해야 할 조치는?\n\n· 외부 침입으로 개인정보가 유출된 정황을 인지했다\n· 아직 유출 규모와 항목은 확인되지 않았다', c:['추가 유출과 확산을 막기 위한 긴급 조치(접근 차단·계정 잠금 등)를 하고 사실 확인과 통지·신고 절차를 병행한다','규모가 확정될 때까지 아무 조치도 하지 않는다','통지·신고 기한과 무관하게 원인 분석을 완료한 뒤 대응한다','언론 대응 자료부터 준비한다'], a:0, e:'확산 방지가 최우선이며 통지·신고 기한(72시간)은 원인 분석 완료를 기다려 주지 않는다.' },
  { s:'s4', t:'악성코드·물리·재해', d:3, q:'다음 〈보기〉에서 재해·재난 대비 조치로 옳은 것을 모두 고른 것은?\n\nㄱ. 화재·홍수·단전 등에 대비한 위기대응 매뉴얼 등 대응 절차를 마련한다\nㄴ. 개인정보처리시스템의 백업 및 복구 계획을 수립한다\nㄷ. 복구 절차의 실효성을 정기적으로 점검하고 훈련한다\nㄹ. 랜섬웨어 대비를 위해 백업본을 분리 보관한다\nㅁ. 매뉴얼만 만들어 두고 점검·훈련은 생략한다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'절차 마련과 함께 정기 점검·훈련이 요구된다.' },
  { s:'s4', t:'적용기준·용어', d:3, q:'다음 대화에서 잘못된 설명을 한 사람은?\n\n· 甲: 안전성 확보조치 기준은 2023년 개정으로 일원화되었습니다\n· 乙: 유형 1·2·3 차등 적용은 폐지되었습니다\n· 丙: 그래도 정보통신서비스 제공자에게는 별도 기준이 그대로 적용됩니다\n· 丁: 일부 조항은 처리 규모에 따라 적용 여부가 달라집니다', c:['甲','乙','丙','丁'], a:2, e:'특례 기준은 폐지·흡수되어 별도 기준은 존재하지 않는다.' },
  { s:'s4', t:'출력·파기', d:3, q:'다음 중 출력·복사 관리로 적절한 것을 모두 고른 것은?\n\nㄱ. 출력 시 용도를 특정하고 필요한 항목만 출력한다\nㄴ. 출력물 관리대장을 두고 반출입을 통제한다\nㄷ. 출력물에 워터마크를 표시해 유출 시 추적성을 확보한다\nㄹ. 폐기 시 파쇄하거나 소각한다\nㅁ. 업무 편의를 위해 출력물을 공용 공간에 비치한다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'출력물은 노출을 최소화하고 안전하게 보관해야 한다.' },
  { s:'s4', t:'내부관리·접근권한', d:3, q:'다음 중 내부 관리계획 운영에 대한 설명으로 옳은 것은?', c:['연 1회 이상 이행 실태를 점검·개선하고 변경 시 사유와 내용을 기록·관리한다','수립 후에는 조직이 바뀌어도 개정할 필요가 없다','점검은 3년마다 하면 충분하다','1만명 이상을 처리하면 수립을 생략할 수 있다'], a:0, e:'생략 가능 기준은 1만명 미만을 처리하는 소상공인·개인·단체다.' },

  /* ───── 5과목 ───── */
  { s:'s5', t:'ISMS-P', d:3, q:'다음 사례에서 G사가 준비해야 할 사항으로 가장 적절한 것은?\n\nG사는 개인정보 110만명을 보유해 ISMS-P 인증 의무 대상이 되었다.\n담당자는 심사 신청만 하면 곧바로 인증을 받을 수 있다고 생각하고 있다.', c:['관리체계를 일정 기간 운영한 실적과 증적이 필요하며, 심사 후 결함에 대해 40일 이내 보완조치를 해야 한다','신청 즉시 인증서가 발급된다','인증은 서면 심사만으로 이루어진다','결함이 발견되어도 보완조치 없이 인증된다'], a:0, e:'절차는 준비·신청·계약·심사·결함 보완·심의의결·발급·사후관리 순이다.' },
  { s:'s5', t:'영향평가(PIA)', d:3, q:'다음 사례에서 영향평가 대상 여부 판단으로 옳은 것은?\n\n· H 공공기관: 7만명의 고유식별정보를 처리하는 신규 파일 구축\n· I 공공기관: 기존 파일과 연계해 60만명이 포함되는 파일 운용\n· J 민간기업: 200만명의 일반 개인정보파일 운용', c:['H와 I는 영향평가 의무 대상이고, J는 법상 의무 대상이 아니라 권장 대상이다','세 곳 모두 의무 대상이다','H만 의무 대상이다','J만 의무 대상이다'], a:0, e:'PIA 의무는 공공기관 대상이며 5만(민감·고유식별)·50만(연계)·100만(규모) 기준이 적용된다.' },
  { s:'s5', t:'수준평가·감사', d:3, q:'다음 〈보기〉에서 공공기관 개인정보 보호수준 평가에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. 종전의 관리수준 진단을 개편한 제도다\nㄴ. 자체평가와 전문가 심층평가로 구성된다\nㄷ. 개인정보 보호위원회가 등급을 부여하고 공표한다\nㄹ. CPO 관련 지표가 신설되었다\nㅁ. 민간 기업도 동일하게 평가 대상이 된다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'평가 대상은 공공기관이다.' },
  { s:'s5', t:'위험관리', d:3, q:'다음 사례에서 K사가 선택한 위험 처리 전략은?\n\nK사는 회원 생일 정보를 이용한 이벤트가 수익에 기여하는 바가 작고\n유출 시 위험이 크다고 판단하여 생일 항목 수집 자체를 중단했다.', c:['회피','수용','전가','감소'], a:0, e:'위험을 발생시키는 활동 자체를 중단하는 것은 회피다.' },
  { s:'s5', t:'위험관리', d:3, q:'다음 〈보기〉에서 관리체계 운영에 대한 설명으로 옳은 것을 모두 고른 것은?\n\nㄱ. PDCA는 계획·실행·점검·개선의 순환 구조다\nㄴ. 위험은 자산·위협·취약점의 관계로 파악하고 영향도를 고려한다\nㄷ. DoA를 초과하는 위험은 처리 대상이 된다\nㄹ. 위험 분석에는 정량적 방법과 정성적 방법이 있다\nㅁ. 잔여 위험이 남아 있으면 관리체계가 실패한 것이다', c:['ㄱ, ㄴ, ㄷ, ㄹ','ㄱ, ㄷ, ㅁ','ㄴ, ㄹ, ㅁ','ㄱ, ㄴ, ㅁ'], a:0, e:'잔여 위험은 DoA 이하로 관리하며 0으로 만드는 것이 목표가 아니다.' },
  { s:'s5', t:'국제표준·프레임워크', d:3, q:'다음 중 상황과 적용할 프레임워크·표준의 연결이 가장 적절한 것은?', c:['침해사고 대응 체계를 식별·보호·탐지·대응·복구 관점으로 설계 — NIST CSF','신규 시스템의 개인정보 침해 위험을 사전 평가 — ISO 19011','정보보호 관리체계 인증 기준 — ISO/IEC 29100','감사 수행 지침 — ISO/IEC 27018'], a:0, e:'사전 위험 평가는 PIA(ISO 29134), 인증 기준은 27001, 감사 지침은 19011이다.' },
  { s:'s5', t:'ISMS-P', d:3, q:'다음 중 ISMS-P 인증 취득 후의 관리로 옳은 것은?', c:['매년 사후심사를 받고 유효기간 만료 전에 갱신심사를 받는다','유효기간 3년 동안 아무런 심사를 받지 않는다','사후심사는 인증기관이 요구할 때만 받는다','갱신심사는 유효기간이 지난 뒤에 받는다'], a:0, e:'사후심사는 연 1회 이상, 갱신심사는 만료 전에 받는다.' },
  { s:'s5', t:'수준평가·감사', d:3, q:'다음 사례에 대한 지적으로 옳은 것은?\n\nL 공공기관은 ISMS-P 인증을 취득한 뒤\n· 보호수준 평가는 인증으로 대체된다고 판단했고\n· 접속기록 월 1회 점검도 인증 심사로 갈음할 수 있다고 보았다', c:['보호수준 평가와 인증은 별개 제도이며 법정 점검 의무도 인증으로 갈음할 수 없다','두 판단 모두 타당하다','보호수준 평가만 대체할 수 있다','법정 점검만 갈음할 수 있다'], a:0, e:'인증·평가·법정 점검은 목적과 근거가 서로 다르다.' }
);
